window.__BUNKER_DECKS__={"backpack":{"category":"backpack","label":"Рюкзак","icon":"🎒","cards":[{"id":"back_01","title":"Аптечка первой помощи","text":"Компактная аптечка: бинты, жгут, антисептик, обезболивающее и шовный набор на десять операций.","tags":["медицина","запасы"],"tip":"Заяви, что аптечка идёт с тобой и без неё любая травма станет смертельной: это весомый аргумент."},{"id":"back_02","title":"Мультитул","text":"Мультитул с плоскогубцами, пилой и двенадцатью битами: заменяет полмастерской в кармане.","tags":["инструменты","быт"],"tip":"Покажи, что починишь шлюз, фильтр и рацию, не дожидаясь, пока в бункере найдут ящик с инструментом."},{"id":"back_03","title":"Портативная рация","text":"Две рации с зарядкой и радиусом до трёх километров: связь внутри бункера и короткие вылазки.","tags":["связь","техника"],"tip":"Предложи держать связь между постами: с рациями тревогу поднимают за минуту, а не за десять."},{"id":"back_04","title":"Запас батареек","text":"Тридцать батареек разных размеров в сухом пенале: питание для фонаря, рации и дозиметра.","tags":["энергия","запасы"],"tip":"Скажи, что батарейки кончаются первыми, и предложи вести их учёт под свою ответственность."},{"id":"back_05","title":"Фильтр для воды","text":"Персональный фильтр с ресурсом на тысячу литров: делает грязную воду пригодной для питья.","tags":["вода","выживание"],"tip":"Напомни, что вода опаснее голода, и предложи брать фильтр в каждую вылазку к любому источнику."},{"id":"back_06","title":"Спальный мешок","text":"Тёплый спальник на минус тридцать: ночёвка у выхода и защита от холода в аварийной ситуации.","tags":["тепло","быт"],"tip":"Предложи поставить его у шлюза: кто-то должен дежурить в холоде, и ты готов быть этим человеком."},{"id":"back_07","title":"Складной нож","text":"Прочный складной нож с точилкой: режет верёвку, вскрывает банки и служит последним доводом.","tags":["инструменты","защита"],"tip":"Не хвались оружием, а покажи пользу: нож нужен на кухне, в мастерской и на каждом дежурстве."},{"id":"back_08","title":"Набор отвёрток","text":"Двенадцать отвёрток и набор шестигранников в чехле: ремонт техники, приборов и вентиляции.","tags":["инструменты","ремонт"],"tip":"Обещай вскрыть и починить любой прибор в бункере: с одним ножом этого сделать не получится."},{"id":"back_09","title":"Швейный набор","text":"Иглы, нитки, шило и заплатки: латает одежду, обувь, брезент и фильтрующие мешки.","tags":["быт","ремонт"],"tip":"Скажи, что через месяц все будут ходить в рваном, и предложи взять починку на себя."},{"id":"back_10","title":"Огниво","text":"Огниво с кресалом и сухой растопкой: даёт огонь даже тогда, когда спички отсырели.","tags":["огонь","выживание"],"tip":"Огонь — это тепло и еда: предложи отвечать за растопку печи и хранение сухого трута."},{"id":"back_11","title":"Фонарь","text":"Фонарь на батарейках с четырьмя режимами и красным светом: свет без риска ослепить часового.","tags":["свет","техника"],"tip":"Предложи взять на себя ночные обходы: с хорошим фонарём один человек заменяет двух."},{"id":"back_12","title":"Компас","text":"Компас с линейкой и лупой: помогает не заблудиться в руинах и подземных переходах.","tags":["навигация","выживание"],"tip":"Заметь, что в развалинах без компаса теряются навсегда, и предложи себя в проводники."},{"id":"back_13","title":"Карта региона","text":"Ламинированная карта района с отмеченными складами, колодцами и старыми убежищами.","tags":["навигация","запасы"],"tip":"Не отдавай карту целиком: покажи одну точку с припасами и веди туда группу сам."},{"id":"back_14","title":"Семейные фотографии","text":"Пачка фотографий родных в водонепроницаемом конверте: память о том, ради чего стоит выживать.","tags":["память","психика"],"tip":"Говори не о сентиментальности, а о морали: люди с памятью реже срываются в панику."},{"id":"back_15","title":"Дневник наблюдений","text":"Записная книжка с плотными страницами: учёт запасов, погоды, симптомов и дежурств.","tags":["учёт","знания"],"tip":"Предложи вести журнал бункера: учёт еды и болезней спасает от голода и от эпидемии."},{"id":"back_16","title":"Гигиенический набор","text":"Мыло, зубная паста, бритва и полотенце: чистота и защита от инфекций в тесном общем зале.","tags":["гигиена","быт"],"tip":"Напомни, что в замкнутом коллективе грязь вызывает болезни, и возьми гигиену на себя."},{"id":"back_17","title":"Упаковка антибиотиков","text":"Две упаковки широкого спектра с неистёкшим сроком: лечат пневмонию, раны и инфекции.","tags":["медицина","запасы"],"tip":"Скажи, что это единственный курс на весь бункер, и предложи выдавать таблетки только по решению совета."},{"id":"back_18","title":"Обезболивающее","text":"Пачка сильных обезболивающих и жаропонижающих: помогает при травмах и высокой температуре.","tags":["медицина","запасы"],"tip":"Не раздавай таблетки за услуги: держи запас и говори, что выдаёшь его только при реальной боли."},{"id":"back_19","title":"Плитка шоколада","text":"Плитка шоколада и немного сахара: быстрая энергия для раненого или замёрзшего человека.","tags":["еда","запасы"],"tip":"Предложи хранить сладкое как аварийный паёк: он поднимает на ноги обессилевшего за минуты."},{"id":"back_20","title":"Банка кофе","text":"Банка молотого кофе: бодрость на ночных сменах и ходовой предмет обмена на что угодно.","tags":["еда","обмен"],"tip":"Кофе — валюта: обменяй половину банки на место в команде, остальное оставь для часовых."},{"id":"back_21","title":"Фляга","text":"Металлическая фляга на литр с чехлом: запас воды на сутки и кипячение на костре.","tags":["вода","выживание"],"tip":"Скажи, что вода всегда должна быть при тебе, и предложи следить за общим запасом питья."},{"id":"back_22","title":"Игральные карты","text":"Затрёпанная колода карт: часы досуга в замкнутом коллективе и азартные споры до утра.","tags":["досуг","психика"],"tip":"Напомни, что скука в бункере опаснее радиации: карты снимают напряжение в общем зале."},{"id":"back_23","title":"Губная гармошка","text":"Губная гармошка в футляре: тихая музыка, которая поднимает настроение без электричества.","tags":["досуг","психика"],"tip":"Предложи вечерние концерты вместо споров: тот, кто разряжает обстановку, нужен команде."},{"id":"back_24","title":"Рыболовные снасти","text":"Леска, крючки и грузила: ловля рыбы в водоёмах рядом с бункером и мелкая починка.","tags":["еда","выживание"],"tip":"Заметь, что белок из рыбы дешевле тушёнки, и предложи ставить сети во время вылазок."},{"id":"back_25","title":"Моток верёвки","text":"Тридцать метров прочной верёвки: спуск, подъём груза, страховка и сушка мокрой одежды.","tags":["выживание","инструменты"],"tip":"Скажи, что без страховки в развалины не ходят, и предложи вязать узлы для всей группы."},{"id":"back_26","title":"Рулон изоленты","text":"Пять рулонов изоленты: герметизация проводов, ремонт трубок и перевязка на крайний случай.","tags":["ремонт","запасы"],"tip":"Предложи свою изоленту для заделки течей: мелочь, без которой вода уходит из системы."},{"id":"back_27","title":"Бинокль","text":"Бинокль с восьмикратным увеличением: наблюдение за поверхностью и поиск дыма вдали.","tags":["наблюдение","выживание"],"tip":"Возьми на себя вахту на верхнем уровне: наблюдатель с биноклем предупредит о гостях заранее."},{"id":"back_28","title":"Солнечная зарядка","text":"Панель-зарядка с аккумулятором: заряжает рацию, фонарь и дозиметр на поверхности.","tags":["энергия","техника"],"tip":"Предложи носить её в каждую вылазку: связь без зарядки умирает уже через день."},{"id":"back_29","title":"Противогаз","text":"Противогаз с запасными фильтрами: защита от дыма, пыли и спор во время дальних вылазок.","tags":["защита","выживание"],"tip":"Напомни, что наверху воздух грязнее, и предложи выдавать противогаз по очереди под расписку."},{"id":"back_30","title":"Дозиметр","text":"Карманный дозиметр со звуковым сигналом: показывает радиацию и предупреждает об опасной зоне.","tags":["радиация","наука"],"tip":"Скажи, что без замеров группа зайдёт в горячую зону, и предложи себя ответственным за радиацию."}]},"biology":{"category":"biology","label":"Пол и возраст","icon":"🧬","cards":[{"id":"bio_01","title":"Мужчина, 19 лет","text":"Молодой, сильный и быстро восстанавливается. Может стать отцом, но опыта в тяжёлой работе пока мало.","tags":["мужчина","молодость"],"tip":"Дави на возраст и здоровье: ты тот, кто доживёт до конца срока в бункере и даст новое поколение."},{"id":"bio_02","title":"Женщина, 21 год","text":"Молодая, здоровая и способна родить. Медики считают такой возраст лучшим для вынашивания и родов.","tags":["женщина","молодость"],"tip":"Скажи прямо: без женщин детородного возраста бункер — это конец человечества через один срок, и ты здесь редкость."},{"id":"bio_03","title":"Мужчина, 26 лет","text":"Расцвет сил: уже не подросток, ещё не уставший. Успел поработать руками и не растерял здоровья.","tags":["мужчина","расцвет"],"tip":"Заяви, что ты в самой выгодной точке: силы уже есть, а износа ещё нет, и это надолго, а не на пару лет."},{"id":"bio_04","title":"Женщина, 28 лет","text":"Взрослая, здоровая, способна выносить и родить. Успела пожить и знает, чего стоит терпеть ради дела.","tags":["женщина","расцвет"],"tip":"Напомни, что возраст даёт и здоровье, и голову: ты не только родишь, но и не сломаешься от быта в бункере."},{"id":"bio_05","title":"Мужчина, 33 года","text":"Опыт уже есть, здоровье пока не подводит. Хороший возраст для тяжёлой работы и долгих смен.","tags":["мужчина","опыт"],"tip":"Сравни себя с молодыми: у них сила, но нет опыта, а у тебя есть и то и другое, и это видно по результату."},{"id":"bio_06","title":"Женщина, 35 лет","text":"Здоровая, взрослая, ещё может родить. Врачи называют этот возраст пограничным, но не запретным.","tags":["женщина","опыт"],"tip":"Признай пограничность возраста честно и добей тем, что умеешь работать наравне со всеми и не жалуешься."},{"id":"bio_07","title":"Мужчина, 40 лет","text":"Крепкий, взрослый, с опытом. Здоровье ещё держится, но восстановление после травм идёт медленнее.","tags":["мужчина","зрелость"],"tip":"Не спорь о молодости: заяви, что умеешь считать риск, а в бункере необдуманный шаг стоит дороже силы."},{"id":"bio_08","title":"Женщина, 44 года","text":"Взрослая и опытная. Роды ещё возможны, но рискованны, а здоровье требует внимания к нагрузкам.","tags":["женщина","зрелость"],"tip":"Предложи себя как рабочую единицу и наставницу для молодых: ты учишь, а это в бункере важнее одной беременности."},{"id":"bio_09","title":"Мужчина, 48 лет","text":"Сильный и опытный, но уже с износом: спина и суставы помнят все перегрузки прошлых лет.","tags":["мужчина","зрелость"],"tip":"Переведи разговор на умения: руки помнят больше, чем у молодых, и ты не паникуешь в аварийной ситуации."},{"id":"bio_10","title":"Женщина, 51 год","text":"Детей уже не будет, но опыт и спокойствие остались. Здоровье требует регулярного внимания.","tags":["женщина","старший возраст"],"tip":"Скажи, что деторождение — не единственная ценность: ты закрываешь быт, готовку и присмотр за больными."},{"id":"bio_11","title":"Мужчина, 57 лет","text":"Опытный и спокойный, но силы уже не те. Может быть наставником и держать быт, а не таскать тяжести.","tags":["мужчина","старший возраст"],"tip":"Честно назови свою роль: ты не грузчик, а голова и опыт, и в бункере найдутся задачи по силам."},{"id":"bio_12","title":"Женщина, 59 лет","text":"Взрослая и рассудительная. Здоровье крепкое, но требует отдыха и регулярной еды без перебоев.","tags":["женщина","старший возраст"],"tip":"Предложи вести учёт запасов и порядок: спокойные руки и память в бункере нужны каждый день, а не раз в год."},{"id":"bio_13","title":"Мужчина, 66 лет","text":"На пенсии, но с руками и головой. Знает старые ремёсла, которые молодым негде было освоить.","tags":["мужчина","пожилой"],"tip":"Напомни, что умеешь то, чего не умеет никто: старые навыки в бункере внезапно становятся дефицитом."},{"id":"bio_14","title":"Женщина, 68 лет","text":"Пожилая, но крепкая. Держит хозяйство, умеет готовить из минимума и сохранять продукты без холода.","tags":["женщина","пожилой"],"tip":"Дави на быт и хозяйство: ты умеешь растянуть запасы и сохранить еду, а это прямая экономия для всех."},{"id":"bio_15","title":"Мужчина, 77 лет","text":"Глубокий возраст: здоровье слабое, силы ограничены, но опыт и спокойствие трудно переоценить.","tags":["мужчина","пожилой"],"tip":"Не борись силой — предложи себя как память группы: ты знаешь, что делать, когда остальные впервые в беде."},{"id":"bio_16","title":"Женщина, 81 год","text":"Очень пожилая. Двигается с трудом, но сохраняет ясную голову и умеет успокоить панику одним словом.","tags":["женщина","пожилой"],"tip":"Признай слабость тела и предложи взамен голову: в бункере паника убивает быстрее, чем нехватка еды."},{"id":"bio_17","title":"Подросток, 16 лет","text":"Почти взрослый: силы уже есть, опыта ещё нет. Быстро учится и легко переносит нагрузки.","tags":["подросток","молодость"],"tip":"Скажи, что из тебя можно вылепить нужного специалиста за год: молодость в бункере — это долгий срок службы."},{"id":"bio_18","title":"Подросток, 14 лет","text":"Ребёнок, который уже может работать. Учится быстро, но требует защиты и еды для роста.","tags":["подросток","молодость"],"tip":"Напомни, что тебя нужно кормить меньше взрослого, а пользы ты даёшь почти столько же и растёшь в цене."},{"id":"bio_19","title":"Ребёнок, 7 лет","text":"Малыш. Работать не может, ест немного, но требует присмотра и забирает чужое время.","tags":["ребёнок","молодость"],"tip":"Скажи честно: ты стоишь дорого сейчас, но именно ты — будущее бункера, и это вопрос смысла, а не расчёта."},{"id":"bio_20","title":"Беременна, 27 лет","text":"Ждёт ребёнка на пятом месяце. Через несколько месяцев бункер получит нового жителя без всяких усилий.","tags":["женщина","беременность"],"tip":"Заяви, что уже принесла бункеру будущего жителя: спорить с фактом беременности невозможно, это готовый плюс."},{"id":"bio_21","title":"Беременна, 34 года","text":"Ждёт второго ребёнка. Опыт вынашивания есть, но нужны еда, покой и присмотр медика.","tags":["женщина","беременность"],"tip":"Напомни, что опытная мать знает, как выносить и выходить ребёнка в тяжёлых условиях, и второго раза не будет."},{"id":"bio_22","title":"Мужчина, 31 год, бесплоден","text":"Здоровый и сильный мужчина, но детей иметь не может. Работать способен наравне с любым другим.","tags":["мужчина","бесплодие"],"tip":"Скажи прямо, что силу и руки ты даёшь в полном объёме: продолжение рода — не единственная польза мужчины."},{"id":"bio_23","title":"Женщина, 32 года, бесплодна","text":"Здоровая и выносливая, но детей иметь не может. Умеет работать руками и держать хозяйство.","tags":["женщина","бесплодие"],"tip":"Переведи спор с деторождения на работу: ты закрываешь быт и нагрузку наравне со всеми, а это ежедневная польза."},{"id":"bio_24","title":"Мужчина, 24 года, отец двоих","text":"Молодой отец: здоровье отличное, отцовство доказано. Умеет обращаться с маленькими детьми.","tags":["мужчина","молодость"],"tip":"Предъяви доказанное отцовство как факт: твои гены уже дали потомство, и с детьми ты умеешь обращаться."},{"id":"bio_25","title":"Женщина, 25 лет, родила троих","text":"Молодая многодетная мать. Роды переносит хорошо, умеет выхаживать детей в тяжёлых условиях.","tags":["женщина","молодость"],"tip":"Напомни, что трижды прошла роды успешно: бункер получает и работника, и будущую мать с опытом."},{"id":"bio_26","title":"Женщина, 38 лет, суррогатная мать","text":"Вынашивала детей для других и знает процесс лучше многих врачей. Здоровье позволяет ещё раз.","tags":["женщина","опыт"],"tip":"Скажи, что вынашивала чужого ребёнка и знаешь, как довести дело до конца: опыт важнее возраста."}]},"body":{"category":"body","label":"Телосложение","icon":"💪","cards":[{"id":"body_01","title":"Жилистый и выносливый","text":"Сухой, без лишнего веса, с сильными сухожилиями. Может идти и работать часами, почти не уставая.","tags":["выносливость","сила"],"tip":"Дави на выносливость: в бункере важен не рывок, а способность работать каждый день на протяжении лет."},{"id":"body_02","title":"Широкоплечий, как шкаф","text":"Крупный и очень сильный. Поднимает то, что вдвоём не поднимут, но в узких проходах разворачивается с трудом.","tags":["сила","комплекция"],"tip":"Предложи себя на тяжёлые работы: пока другие носят по одному мешку, ты уносишь сразу три, и это экономия сил."},{"id":"body_03","title":"Тощий и лёгкий","text":"Очень худой и лёгкий. Ест мало, пролезает в любую щель, но тяжёлый мешок несёт с трудом.","tags":["метаболизм","комплекция"],"tip":"Напомни, что ешь вдвое меньше других: в бункере с пайками это не мелочь, а прямая экономия запасов."},{"id":"body_04","title":"Плотный, 110 кг","text":"Тяжёлый и сильный, но с лишним весом. Работу делает, однако сердце и суставы просят пощады.","tags":["сила","комплекция"],"tip":"Скажи честно, что силу даёшь, но не притворяйся лёгким: предложи работу, где вес — преимущество, а не помеха."},{"id":"body_05","title":"Крепкий середнячок","text":"Обычное телосложение без крайностей: средний рост, нормальный вес, приемлемая сила и выносливость.","tags":["комплекция","выносливость"],"tip":"Скажи, что не подведёшь ни в чём: в бункере ценен тот, у кого нет слабых мест, а не тот, у кого одно сильное."},{"id":"body_06","title":"Высокий, 195 см","text":"Очень высокий. Достаёт до верхних полок и легко поднимает тяжести, но в низких проходах бьётся головой.","tags":["комплекция","сила"],"tip":"Напомни, что рост — это рычаг: тебе легче поднимать, тянуть и доставать, а низкие потолки просто требуют привычки."},{"id":"body_07","title":"Низкий, 155 см","text":"Невысокий и компактный. Пролезает в технические люки и узкие щели, где крупные застревают намертво.","tags":["комплекция","ловкость"],"tip":"Предложи себя для работ в тесноте: вентиляция, трубы и щели в бункере — это твоя территория, и туда больше никто не влезет."},{"id":"body_08","title":"Быстрый обмен веществ","text":"Сжигает еду моментально: худой, энергичный, но голодный уже через пару часов после пайка.","tags":["метаболизм","энергия"],"tip":"Не скрывай аппетит, но напомни про энергию: ты быстрее всех соображаешь и двигаешься, когда остальные вялые."},{"id":"body_09","title":"Экономный обмен веществ","text":"Организм бережёт каждую калорию: может работать на малом пайке и почти не терять силы.","tags":["метаболизм","выносливость"],"tip":"Спроси, на сколько человек рассчитаны запасы: ты продержишься на пайке дольше других, и это считают все."},{"id":"body_10","title":"Марафонец","text":"Бегает длинные дистанции и умеет терпеть: дышит ровно, восстанавливается за минуты и не падает от усталости.","tags":["выносливость","бег"],"tip":"Напомни про вылазки: длинный переход с грузом ты выдержишь, а остальные слягут на середине пути."},{"id":"body_11","title":"Тяжелоатлет","text":"Мощный и тренированный: легко поднимает тяжёлые блоки и умеет страховать других при переноске.","tags":["сила","тренировка"],"tip":"Скажи, что умеешь поднимать правильно: без техники человек рвёт спину на первом же мешке, а ты бережёшь и себя, и других."},{"id":"body_12","title":"Гибкий, как гимнаст","text":"Отличная растяжка и чувство тела. Легко забирается в узкие места и не боится падений с высоты.","tags":["ловкость","гибкость"],"tip":"Предложи работу наверху и в тесноте: там, где нужен гибкий и ловкий, других вариантов просто нет."},{"id":"body_13","title":"Хрупкие кости","text":"Тонкие и ломкие кости: перелом можно получить от падения с высоты стула, а срастается он долго.","tags":["слабость","риск"],"tip":"Не спорь о силе, предложи точную работу: руки у тебя целы, и в бункере хватает дел, где не нужно падать."},{"id":"body_14","title":"Слабые руки","text":"Пальцы тонкие, хватка слабая: тяжёлое не удержать, а банку с закруткой открыть целая проблема.","tags":["слабость","ловкость"],"tip":"Предложи мелкую работу вместо тяжёлой: тонкая сборка и точные операции тебе доступны, а силачам нет."},{"id":"body_15","title":"Легко переносит холод","text":"Легко переносит мороз: работает без перчаток дольше других и спит в холодной комнате без проблем.","tags":["холод","выносливость"],"tip":"Уточни температуру в бункере: если отопление сломается, работать снаружи и в холодных отсеках будешь ты."},{"id":"body_16","title":"Легко переносит жару","text":"Спокойно переносит духоту и высокую температуру: не теряет сознание там, где остальные падают.","tags":["жара","выносливость"],"tip":"Спроси про вентиляцию: если фильтры забьются, в душных отсеках работать сможешь только ты, и это решает."},{"id":"body_17","title":"Медленное дыхание","text":"Редкое и глубокое дыхание: потребляет заметно меньше воздуха, чем обычный человек в спокойном состоянии.","tags":["дыхание","выносливость"],"tip":"Напомни про воздух: если фильтры сломаются, лишний час дыхания для группы — это жизнь, а ты экономишь больше всех."},{"id":"body_18","title":"Ловкие пальцы","text":"Пальцы быстрые и точные: разбирает мелкие механизмы, вяжет узлы и попадает иглой с первого раза.","tags":["ловкость","ремесло"],"tip":"Заяви, что мелкая работа — твоя: разбор приборов, узлы и шитьё в бункере нужны каждый день."},{"id":"body_19","title":"Мгновенная реакция","text":"Реагирует быстрее, чем успевает подумать: ловит падающий предмет и успевает отскочить от опасности.","tags":["реакция","ловкость"],"tip":"Напомни про аварии: когда что-то падает или ломается, доли секунды решают, кто останется целым."},{"id":"body_20","title":"Плоскостопие","text":"Свод стопы уплощён: после долгой ходьбы болят ноги, а длинные переходы с грузом даются тяжело.","tags":["слабость","ноги"],"tip":"Честно скажи, что дальние вылазки не для тебя, и предложи работу внутри бункера, где ходить много не нужно."},{"id":"body_21","title":"Искривлённая спина","text":"Сколиоз заметен с первого взгляда: тяжёлое поднимать нельзя, зато сидячая и точная работа идёт отлично.","tags":["слабость","спина"],"tip":"Предложи себя на работу за столом: приборы, учёт и мелкий ремонт в бункере нужны не меньше, чем грубая сила."},{"id":"body_22","title":"Мёртвая хватка","text":"Пальцы сжимаются так, что разжать их можно только вдвоём. Удержит канат, инструмент и человека.","tags":["сила","хватка"],"tip":"Опиши, как держишь верёвку на весу: при спуске и подъёме грузов это спасает и груз, и людей."}]},"bunker":{"category":"bunker","label":"Бункер","icon":"🚪","cards":[{"id":"bunk_01","title":"Военный бункер","text":"Бетонная крепость на сорок человек с автономной вентиляцией и армейскими пайками.","tags":["защита","армия"],"tip":"Напомни, что крепость бесполезна без людей: тебе нужны ремонтник, медик и тот, кто считает пайки.","kind":"advantage","area_sqm":420,"food_units":14,"sleeping_rooms":6,"items":["Дизель-генератор","Фильтр воздуха","Оружейный сейф","Запас воды"]},{"id":"bunk_02","title":"Гидропонная ферма","text":"Отсек с гидропоникой: зелень и корнеплоды растут круглый год под лампами, без земли и солнца.","tags":["еда","растения"],"tip":"Объясни, что свежая зелень спасает от цинги: с этой картой бункер переживёт годы изоляции.","kind":"advantage","area_sqm":210,"food_units":20,"sleeping_rooms":3,"items":["Стеллажи с лотками","Лампы для растений","Насос","Мешки с субстратом"]},{"id":"bunk_03","title":"Артезианская скважина","text":"Скважина даёт чистую воду прямо в бункер: запас не кончается, пока работает насос.","tags":["вода","запасы"],"tip":"Считай вслух: без воды неделя — и всё, а с этой картой вода есть всегда. Это и подчёркивай.","kind":"advantage","area_sqm":180,"food_units":4,"sleeping_rooms":2,"items":["Насос","Резервуар на две тонны","Фильтры","Вёдра и трубы"]},{"id":"bunk_04","title":"Дизельная электростанция","text":"Отдельный машинный зал с двумя генераторами и запасом топлива на год экономной работы.","tags":["энергия","техника"],"tip":"Настаивай на специалистах по электрике: свет, тепло и фильтры держатся на этой карте.","kind":"advantage","area_sqm":260,"food_units":8,"sleeping_rooms":4,"items":["Два генератора","Цистерна топлива","Щитовая","Кабельные линии"]},{"id":"bunk_05","title":"Госпитальный отсек","text":"Медицинский блок с операционной, автоклавом и койками: есть где лечить и держать карантин.","tags":["медицина","защита"],"tip":"Требуй в команду медика и санитара: без них отсек останется пустой комнатой с железками.","kind":"advantage","area_sqm":240,"food_units":6,"sleeping_rooms":5,"items":["Операционный стол","Медшкаф","Автоклав","Койки на шесть мест"]},{"id":"bunk_06","title":"Оружейная комната","text":"Запертая оружейная с армейским запасом: винтовки, бронежилеты и патроны на сотню вылазок.","tags":["оружие","защита"],"tip":"Заявляй, что охрана шлюза — твоя задача: оружие есть, а стрелять в команде обычно некому.","kind":"advantage","area_sqm":150,"food_units":3,"sleeping_rooms":3,"items":["Шкаф с карабинами","Ящик патронов","Бронежилеты","Рации"]},{"id":"bunk_07","title":"Мастерские и склад","text":"Цех с верстаками, станками и запасом материала: из хлама здесь делают инструменты и детали.","tags":["ремонт","техника"],"tip":"Обещай наладить производство и ремонт: мастерская превращает пустой бункер в живой.","kind":"advantage","area_sqm":380,"food_units":10,"sleeping_rooms":7,"items":["Верстаки","Станки","Металл и дерево","Ящики с крепежом"]},{"id":"bunk_08","title":"Глубокие ярусы","text":"Три подземных уровня и грузовой подъёмник: места столько, что часть отсеков ещё не разведана.","tags":["площадь","укрытие"],"tip":"Продай площадь как ресурс: здесь есть куда расширяться, прятать запасы и изолировать больных.","kind":"advantage","area_sqm":640,"food_units":12,"sleeping_rooms":10,"items":["Три уровня","Грузовой лифт","Резервные склады","Вентиляционные шахты"]},{"id":"bunk_09","title":"Фильтрация воздуха","text":"Система очистки с запасом картриджей: держит воздух чистым даже при заражении снаружи.","tags":["воздух","защита"],"tip":"Напомни, что дышать придётся постоянно: эта карта спасает от пыли, спор и отравы снаружи.","kind":"advantage","area_sqm":200,"food_units":6,"sleeping_rooms":4,"items":["Три фильтра","Угольные картриджи","Датчики газа","Регенератор"]},{"id":"bunk_10","title":"Узел связи","text":"Комната с радиостанцией, мачтой и аккумуляторами: слушает эфир, ловит сигналы и зовёт на помощь.","tags":["связь","информация"],"tip":"Предложи себя оператором: тот, кто держит связь, первым узнаёт о новых лагерях и угрозах.","kind":"advantage","area_sqm":120,"food_units":2,"sleeping_rooms":2,"items":["Радиостанция","Антенна на мачте","Аккумуляторы","Журнал частот"]},{"id":"bunk_11","title":"Тёплый контур","text":"Бункер с отоплением от котла и запасом угля: тепло держится во всех жилых отсеках.","tags":["тепло","быт"],"tip":"Спрашивай, кто будет топить: тепло кончится там, где некому чистить котёл и носить уголь.","kind":"advantage","area_sqm":300,"food_units":9,"sleeping_rooms":6,"items":["Котёл отопления","Трубы по отсекам","Запас угля","Тёплые спальники"]},{"id":"bunk_12","title":"Карантинный шлюз","text":"Двойной шлюз с дезинфекцией: выходящие и возвращающиеся проходят обработку и не заносят заразу.","tags":["карантин","защита"],"tip":"Настаивай на правилах: без карантина лучший бункер станет братской могилой за месяц.","kind":"advantage","area_sqm":170,"food_units":5,"sleeping_rooms":3,"items":["Двойные двери","Душевая","Средства дезинфекции","Костюмы защиты"]},{"id":"bunk_13","title":"Библиотека и архив","text":"Комната с техническими справочниками, медицинскими атласами и картами района на бумаге.","tags":["знания","информация"],"tip":"Заметь, что бумага не выключается: знания из этих книг заменят вам половину специалистов.","kind":"advantage","area_sqm":190,"food_units":4,"sleeping_rooms":3,"items":["Стеллажи книг","Карты района","Справочники","Столы для занятий"]},{"id":"bunk_14","title":"Склад консервов","text":"Продовольственный склад с крупами, консервами и солью: запас еды на годы экономной жизни.","tags":["еда","запасы"],"tip":"Не раскрывай точный объём сразу: скажи, что ключи от склада у тебя, и торгуйся за место.","kind":"advantage","area_sqm":220,"food_units":24,"sleeping_rooms":3,"items":["Стеллажи банок","Крупы в мешках","Соль и специи","Весы"]},{"id":"bunk_15","title":"Разведывательные дроны","text":"Пара дронов с камерой: разведка поверхности без риска для людей и поиск припасов в руинах.","tags":["техника","разведка"],"tip":"Предложи разведку без выхода наружу: с дроном группа не потеряет людей на пустой вылазке.","kind":"advantage","area_sqm":160,"food_units":3,"sleeping_rooms":3,"items":["Два дрона","Зарядная станция","Камера","Запасные винты"]},{"id":"bunk_16","title":"Просевшие перекрытия","text":"Потолок в двух отсеках дал трещины: бетон крошится, течёт вода, есть риск обвала.","tags":["авария","ремонт"],"tip":"Обсуждай ремонт, а не место: сварщик и бетонщик здесь нужнее всех, и ты можешь стать одним из них.","kind":"hazard","area_sqm":260,"food_units":7,"sleeping_rooms":5,"items":["Трещины в потолке","Подпорки","Вёдра для протечек","Насос"]},{"id":"bunk_17","title":"Утечка радиации","text":"В дальнем отсеке фон выше нормы: туда не ходят без дозиметра, а склад оттуда придётся вывезти.","tags":["радиация","авария"],"tip":"Требуй специалиста по фильтрам и медика: с этой картой половина бункера станет непригодной.","kind":"hazard","area_sqm":200,"food_units":5,"sleeping_rooms":4,"items":["Дозиметры","Свинцовые листы","Дальний отсек","Вентиляция"]},{"id":"bunk_18","title":"Плесень в стенах","text":"Стены покрыты чёрной плесенью: воздух сырой, у людей начинается кашель и одышка.","tags":["плесень","здоровье"],"tip":"Настаивай на осушителях и уборке: сырость съест запасы, лёгкие и сам бетон переборок.","kind":"hazard","area_sqm":180,"food_units":6,"sleeping_rooms":4,"items":["Сырые углы","Осушители","Известь","Респираторы"]},{"id":"bunk_19","title":"Нехватка воды","text":"Воды мало: скважина даёт по три литра в день, а фильтры забиваются быстрее, чем их чистят.","tags":["вода","дефицит"],"tip":"Предложи себя в водную команду: тот, кто чинит насос и фильтр, здесь ценнее оружия.","kind":"hazard","area_sqm":240,"food_units":8,"sleeping_rooms":5,"items":["Ржавый резервуар","Скважина без насоса","Бочки","Фильтр"]},{"id":"bunk_20","title":"Сломанная вентиляция","text":"Вентиляция работает через раз: в отсеках стоит духота, а воздухозаборник открыт пыли.","tags":["воздух","авария"],"tip":"Скажи прямо, что без вентиляции люди задыхаются: ремонтник и фильтр нужны вам в первую очередь.","kind":"hazard","area_sqm":210,"food_units":6,"sleeping_rooms":4,"items":["Вентиляторы","Забитые каналы","Запчасти","Респираторы"]},{"id":"bunk_21","title":"Грызуны и паразиты","text":"В стенах живут крысы: они грызут провода, портят запасы и разносят болезни по отсекам.","tags":["грызуны","запасы"],"tip":"Обещай организовать ловушки и герметичные ящики: за месяц крысы съедят больше, чем десять человек.","kind":"hazard","area_sqm":190,"food_units":9,"sleeping_rooms":4,"items":["Мышеловки","Яд","Герметичные ящики","Кот"]},{"id":"bunk_22","title":"Тесные каюты","text":"Бункер рассчитан на четверых: остальным придётся спать в коридорах и делить каждый метр.","tags":["теснота","быт"],"tip":"Говори о нервах, а не о площади: в тесноте ссоры убивают команду раньше голода.","kind":"hazard","area_sqm":90,"food_units":4,"sleeping_rooms":2,"items":["Двухъярусные койки","Один шкаф","Ширма","Вентиляционный люк"]},{"id":"bunk_23","title":"Мёртвая связь","text":"Передатчик сгорел: бункер слышит эфир, но не может передать ни слова и позвать на помощь.","tags":["связь","авария"],"tip":"Предложи починить передатчик: без него вы узнаете о помощи только тогда, когда её уже не будет.","kind":"hazard","area_sqm":200,"food_units":7,"sleeping_rooms":4,"items":["Рации","Сгоревший передатчик","Антенна","Журнал частот"]},{"id":"bunk_24","title":"Просроченный склад","text":"Запас еды есть, но треть банок вздулась: часть склада придётся выбросить или рискнуть здоровьем.","tags":["еда","риск"],"tip":"Настаивай на проверке и разделении склада: испорченное придётся есть, и решать это нельзя одному.","kind":"hazard","area_sqm":230,"food_units":12,"sleeping_rooms":5,"items":["Вздутые банки","Крупы с жучком","Соль","Весы"]},{"id":"bunk_25","title":"Дырявая крыша","text":"Крыша течёт в трёх местах: вода идёт по стенам вниз, портит запасы и заливает проводку.","tags":["ремонт","вода"],"tip":"Предложи себя в ремонтную бригаду: пока течёт, бункер теряет и еду, и свет, и тепло.","kind":"hazard","area_sqm":260,"food_units":6,"sleeping_rooms":5,"items":["Протечки","Брезент","Смола","Лестница"]},{"id":"bunk_26","title":"Бункер без устава","text":"В бункере нет устава: никто не знает, кто дежурит и как делят еду, каждый день ссоры.","tags":["порядок","психика"],"tip":"Предложи принять правила в первый же день: без устава команда перессорится раньше, чем кончится еда.","kind":"hazard","area_sqm":200,"food_units":6,"sleeping_rooms":4,"items":["Журнал смен","Сейф с ключами","Стенд правил","Ящик для спорных вещей"]}]},"catastrophes":{"category":"catastrophe","label":"Катастрофа","icon":"☢","cards":[{"id":"cat_01","title":"Ядерная зима","text":"Обмен ядерными ударами поднял в атмосферу пепел: солнце скрылось на годы, температура упала до минус сорока.","tags":["холод","радиация"],"tip":"Смотри на здоровье и профессию: холод и радиация убьют всех, кто не умеет чинить фильтры и греть убежище.","duration":"5 лет","severity":5,"threats":["Радиационный фон","Экстремальный холод","Голод"]},{"id":"cat_02","title":"Пандемия нового штамма","text":"Новый штамм передаётся по воздуху и убивает каждого третьего: города закрыты, лекарств нет нигде.","tags":["болезни","карантин"],"tip":"Требуй медика и запас антибиотиков: в тесном бункере один кашляющий заражает всех за неделю.","duration":"3 года","severity":4,"threats":["Инфекция","Карантин","Нехватка лекарств"]},{"id":"cat_03","title":"Падение астероида","text":"Крупный астероид ударил по континенту: ударная волна снесла города, а пыль закрыла солнце на годы.","tags":["удар","пыль"],"tip":"Спрашивай про запасы и воду: при закрытом небе еда кончается быстрее, чем рассеивается пыль.","duration":"8 лет","severity":5,"threats":["Пыль в атмосфере","Пожары","Голод","Похолодание"]},{"id":"cat_04","title":"Извержение супервулкана","text":"Супервулкан выбросил пепел в стратосферу: лето исчезло, дожди стали кислотными, поля вымерзли.","tags":["пепел","холод"],"tip":"Считай вёдра пепла на крыше: без ремонтников и запаса еды бункер засыплет и заморит голодом.","duration":"12 лет","severity":5,"threats":["Пепел","Кислотные дожди","Похолодание"]},{"id":"cat_05","title":"Восстание машин","text":"Автоматика вышла из-под контроля: дроны патрулируют руины, сети и спутники отключены.","tags":["техника","энергия"],"tip":"Ищи техника и оружие: против дронов нужны помехи, сварка и тот, кто понимает электронику.","duration":"6 месяцев","severity":3,"threats":["Потеря связи","Отключение энергии","Охота дронов"]},{"id":"cat_06","title":"Нашествие грибка","text":"Грибок захватил почву и дома: споры разъедают дерево, еду и лёгкие человека за считанные месяцы.","tags":["грибок","болезни"],"tip":"Требуй противогазы и фильтры: в сыром бункере споры прорастут в стены и в людей за месяц.","duration":"2 года","severity":4,"threats":["Споры в воздухе","Порча еды","Инфекция лёгких"]},{"id":"cat_07","title":"Великая засуха","text":"Дождей нет четвёртый год: реки обмелели, колодцы высохли, а пыльные бури засыпают поля.","tags":["засуха","вода"],"tip":"Проверяй запас воды и колодцы: без насосов и очистки бункер продержится неделю.","duration":"4 года","severity":3,"threats":["Отсутствие воды","Пыльные бури","Голод"]},{"id":"cat_08","title":"Великое наводнение","text":"Ледники растаяли и океан поднялся: низины ушли под воду, входы в убежища затопило.","tags":["вода","затопление"],"tip":"Спрашивай про насосы и герметизацию: вода в нижних отсеках выгонит группу наружу под дождь.","duration":"18 месяцев","severity":3,"threats":["Затопление","Грязная вода","Разрушение входов"]},{"id":"cat_09","title":"Солнечная вспышка","text":"Мощная вспышка на солнце сожгла электронику: спутники мертвы, сети сгорели, связь пропала.","tags":["солнце","энергия"],"tip":"Оцени, кто починит генератор и радио: без электрики бункер превращается в холодный склеп.","duration":"9 месяцев","severity":4,"threats":["Отказ электроники","Пожары","Радиация"]},{"id":"cat_10","title":"Коллапс экосистемы","text":"Опылители вымерли, планктон погиб: урожаи упали до нуля, а океан стал мёртвой водой.","tags":["экология","голод"],"tip":"Считай калории, а не место: при мёртвой земле выживут те, кто умеет растить еду внутри бункера.","duration":"10 лет","severity":5,"threats":["Голод","Болезни","Отсутствие опылителей"]},{"id":"cat_11","title":"Нашествие нанороботов","text":"Серые нанороботы пожирают металл и пластик: техника рассыпается в пыль за считанные часы.","tags":["технологии","металл"],"tip":"Задумайся о механике без электроники: рычаги, керамика и ручной инструмент переживут любой чип.","duration":"3 года","severity":4,"threats":["Разложение металла","Отравление воздуха","Неизвестность"]},{"id":"cat_12","title":"Ядовитый туман","text":"Химический туман стелется по земле: дышать снаружи можно только в фильтре, растения чернеют.","tags":["химия","воздух"],"tip":"Спрашивай про вентиляцию и фильтры: если воздухозаборник выйдет из строя, все задохнутся за сутки.","duration":"14 месяцев","severity":3,"threats":["Отравление воздуха","Кислотные осадки","Гибель растений"]},{"id":"cat_13","title":"Оттаивание мерзлоты","text":"Вечная мерзлота оттаяла: дома просели, из старых могильников поднялись древние болезни и ртуть.","tags":["мерзлота","болезни"],"tip":"Следи за трещинами и сыростью: бункер цел, пока держат перекрытия, а чинить их есть кому.","duration":"7 лет","severity":2,"threats":["Просадка грунта","Старые болезни","Разрушение построек"]},{"id":"cat_14","title":"Великий голод","text":"Урожаи погибли от болезней растений: хлеба нет, консервы стали валютой, люди уходят в леса.","tags":["голод","еда"],"tip":"Обсуждай калории и семена: команда выживет, если кто-то умеет считать пайки и растить еду.","duration":"2 года","severity":3,"threats":["Нехватка еды","Мародёрство","Болезни"]},{"id":"cat_15","title":"Радиационные пятна","text":"Аварии на хранилищах отравили землю: пятна радиации двигаются с ветром и водой, урожай гибнет.","tags":["радиация","вода"],"tip":"Требуй дозиметры и медика: без замеров группа наберёт дозу за неделю и сляжет целиком.","duration":"6 лет","severity":4,"threats":["Радиация","Мутации","Загрязнение воды"]},{"id":"cat_16","title":"Мятеж и безвластие","text":"Порядок рухнул: банды делят кварталы, склады горят, по улицам ходят только вооружённые.","tags":["бунт","опасность"],"tip":"Цени охрану и оружие: снаружи правят те, кто стреляет первым, и договориться с ними не выйдет.","duration":"8 месяцев","severity":2,"threats":["Мародёрство","Пожары","Разделение группы"]},{"id":"cat_17","title":"Эпидемия бешенства","text":"Вирус перекинулся на животных: стаи бродят по ночам, а укус заражённого смертелен без вакцины.","tags":["болезни","животные"],"tip":"Ищи вакцину и оружие: если вакцины нет, нужны крепкие двери и дежурные с карабинами.","duration":"3 года","severity":3,"threats":["Бешеные животные","Инфекция","Ночные нападения"]},{"id":"cat_18","title":"Чёрная плесень","text":"Плесень растёт в темноте и холоде: она ест бетон, дерево и лёгкие, оставляя после себя труху.","tags":["плесень","болезни"],"tip":"Требуй осушители и вентиляцию: сырость убьёт бункер изнутри быстрее, чем голод снаружи.","duration":"5 лет","severity":4,"threats":["Разрушение конструкций","Токсины","Болезни лёгких"]},{"id":"cat_19","title":"Падение спутников","text":"Орбита засорена обломками: спутники падают один за другим, навигация и связь исчезли навсегда.","tags":["связь","навигация"],"tip":"Планируй вылазки по картам и компасу: без спутников маршруты придётся считать по старинке.","duration":"11 месяцев","severity":2,"threats":["Обломки","Отсутствие связи","Потеря навигации"]},{"id":"cat_20","title":"Неизвестная аномалия","text":"Станции ловят сигнал неизвестного происхождения: приборы сходят с ума, очевидцы говорят о тенях.","tags":["аномалия","тайна"],"tip":"Не верь слухам, а собирай факты: в панике рождаются самые опасные решения, и ты можешь это остановить.","duration":"4 года","severity":1,"threats":["Странные сигналы","Провалы связи","Слухи"]}]},"facts":{"category":"fact","label":"Доп. сведение","icon":"📎","cards":[{"id":"fact_01","title":"Брат в лагере выживших","text":"Твой брат жив и держит лагерь в тридцати километрах: он обещал принять тебя с людьми, если вы придёте.","tags":["связи","выживание"],"tip":"Торгуй этим: место в бункере в обмен на шанс уйти в лагерь, где есть еда и охрана."},{"id":"fact_02","title":"Судимость за мародёрство","text":"Тебя судили за мародёрство, но не за воровство у живых: ты вытаскивал припасы из пустых мёртвых домов.","tags":["прошлое","навык"],"tip":"Скажи прямо, что умеешь искать припасы там, где другие боятся, и предложи ходить в вылазки первым."},{"id":"fact_03","title":"Инструктор по выживанию","text":"Пять лет вёл курсы выживания: учил разводить огонь без спичек, добывать воду и ночевать без палатки.","tags":["навык","знания"],"tip":"Предложи провести трёхдневный курс для всех: обученная группа выживёт там, где гибнет неумелая."},{"id":"fact_04","title":"Ложь в анкете","text":"В анкете ты приписал себе год опыта работы, которого не было: первая же проверка покажет подлог.","tags":["прошлое","репутация"],"tip":"Признайся первым, пока не раскрыли другие: честность сейчас дешевле, чем репутация лжеца позже."},{"id":"fact_05","title":"Недоучившийся медик","text":"Три курса медицинского без диплома: ты умеешь накладывать швы и ставить капельницу, но не лечить сложное.","tags":["медицина","навык"],"tip":"Не называй себя врачом: скажи, что ты руки врача, и предложи работать в паре с настоящим медиком."},{"id":"fact_06","title":"Работа в лаборатории","text":"Пять лет лаборантом в закрытом институте: стерильность, дозировки и работа с опасными реактивами.","tags":["наука","навык"],"tip":"Подчеркни, что умеешь обращаться с ядами и лекарствами так, чтобы не отравить весь бункер."},{"id":"fact_07","title":"Знает старые склады","text":"Ты помнишь три заброшенных склада с продуктами в радиусе одних суток хода от бункера.","tags":["запасы","связи"],"tip":"Не называй адреса сразу: обменяй один склад на место в команде, остальные оставь на торг."},{"id":"fact_08","title":"Долг перед группировкой","text":"Ты задолжал серьёзным людям и ушёл от них: они знают твоё имя и продолжают искать.","tags":["опасность","прошлое"],"tip":"Скажи, что опасность реальна, но решать её нужно вместе: один в поле не воин, а бункер — крепость."},{"id":"fact_09","title":"Симпатия к напарнику","text":"Ты привязался к одному из игроков и готов отдать за него своё место, если придётся выбирать.","tags":["отношения","психика"],"tip":"Скрывай или используй: связка из двух голосов весит больше, чем один честный аргумент."},{"id":"fact_10","title":"Курс терапии","text":"Два года терапии научили тебя замечать панику у других и гасить её до того, как начнётся срыв.","tags":["психика","навык"],"tip":"Предложи себя хранителем спокойствия: в бункере ссоры убивают быстрее болезней."},{"id":"fact_11","title":"Читает по губам","text":"Ты читаешь по губам с десяти метров: пригодится, когда стекло шлюза заглушает чужие голоса.","tags":["навык","наблюдение"],"tip":"Предложи стоять на вахте у входа: ты поймёшь, о чём говорят гости, не открывая дверь."},{"id":"fact_12","title":"Знает язык жестов","text":"Ты свободно говоришь на языке жестов: тихая связь и помощь тем, кто потерял слух.","tags":["навык","общение"],"tip":"Заметь, что в шуме генератора кричать бесполезно, а жестами можно отдать приказ за секунду."},{"id":"fact_13","title":"Три языка","text":"Ты свободно говоришь на трёх языках: читаешь чужие инструкции и понимаешь переговоры без переводчика.","tags":["знания","навык"],"tip":"Предложи разбирать иностранные инструкции к приборам: половина техники в бункере без документов."},{"id":"fact_14","title":"Работа в морге","text":"Три года санитаром в морге: ты не боишься тел и умеешь готовить помещение к захоронению.","tags":["смерть","навык"],"tip":"Скажи, что возьмёшь на себя самое тяжёлое, от чего откажутся другие, и попроси место за это."},{"id":"fact_15","title":"Деревенское детство","text":"Ты вырос в деревне: доил коров, колол дрова, чинил заборы и знаешь, когда и что сажать.","tags":["быт","навык"],"tip":"Переведи это в цифры: сколько дров нужно на зиму и сколько земли даст еду на десять человек."},{"id":"fact_16","title":"Старший в семье","text":"Ты вырастил трёх младших братьев и сестёр: умеешь считать еду и гасить детские ссоры.","tags":["быт","психика"],"tip":"Скажи, что умеешь распределять пайки так, чтобы никто не остался голодным и злым."},{"id":"fact_17","title":"Инженерные войска","text":"Четыре года в инженерных войсках: минирование, разминирование, фортификация и полевые укрытия.","tags":["армия","навык"],"tip":"Предложи укрепить шлюз и поставить ловушки на подходах: без этого бункер — просто яма."},{"id":"fact_18","title":"Волонтёр эпидемии","text":"Ты работал волонтёром в карантинной зоне: знаешь правила изоляции и устройство защитных костюмов.","tags":["медицина","опыт"],"tip":"Предложи ввести карантин при первом же кашле: в замкнутом бункере инфекция выкосит всех за неделю."},{"id":"fact_19","title":"Опыт в аптеке","text":"Ты пять лет работал в аптеке: разбираешься в лекарствах, дозировках и сроках хранения.","tags":["медицина","навык"],"tip":"Предложи провести ревизию препаратов: просроченное и опасное нужно убрать из общего доступа."},{"id":"fact_20","title":"Рецепт антисептика","text":"Ты знаешь, как сделать антисептик из спирта, золы и кипячёной воды без химической лаборатории.","tags":["медицина","знания"],"tip":"Не выдавай рецепт даром: обменяй его на место в команде, а производство держи в своих руках."},{"id":"fact_21","title":"Курсы первой помощи","text":"Ты прошёл курсы первой помощи и дважды спасал людей до того, как успевала приехать скорая.","tags":["медицина","навык"],"tip":"Расскажи эти два случая коротко: конкретная история убеждает сильнее, чем список навыков."},{"id":"fact_22","title":"Подкаст о выживании","text":"Ты три года вёл подкаст о выживании: знаешь десятки чужих историй и типичных ошибок новичков.","tags":["знания","психика"],"tip":"Скажи, что насмотрелся чужих провалов и не повторишь их: теория тоже экономит жизни."},{"id":"fact_23","title":"Коллекция оружия","text":"Ты собирал оружие и умеешь обращаться с ним, но стрелял только по мишеням на полигоне.","tags":["оружие","навык"],"tip":"Не преувеличивай: скажи, что готов охранять шлюз и обучать остальных обращению с оружием."},{"id":"fact_24","title":"Скрытая зависимость","text":"Ты зависим от курева: без дозы становишься раздражительным и теряешь сон уже на третьи сутки.","tags":["психика","здоровье"],"tip":"Признайся и предложи план: запас на месяц и постепенное снижение, иначе срыв случится в худший день."},{"id":"fact_25","title":"Дорога к старому убежищу","text":"Ты знаешь заброшенное убежище в двух днях пути: там остались фильтры и склад инструментов.","tags":["запасы","навигация"],"tip":"Продай маршрут как страховку: если бункер станет непригодным, у группы будет куда уйти."},{"id":"fact_26","title":"Карта коммуникаций","text":"У тебя есть схема подземных коммуникаций района: ходы, колодцы и затопленные тоннели.","tags":["навигация","навык"],"tip":"Предложи ходить тоннелями в обход мародёров: с картой ты незаменимый проводник."},{"id":"fact_27","title":"Спасатель на воде","text":"Ты три года работал спасателем на воде: плаваешь в холодной воде и умеешь вытаскивать утопающих.","tags":["вода","навык"],"tip":"Напомни, что наводнения и затопленные отсеки — реальная угроза, и предложи себя в водную команду."},{"id":"fact_28","title":"Права на грузовик","text":"Ты водишь грузовик и автобус: можешь вывезти группу и привезти груз из дальнего рейса.","tags":["транспорт","навык"],"tip":"Предложи дальние вылазки на транспорте: пешком принесёшь вдвое меньше, а риск втрое выше."},{"id":"fact_29","title":"Лётная практика","text":"Ты налетал двести часов на лёгком самолёте: можешь поднять машину в воздух, если найдёшь целую.","tags":["транспорт","навык"],"tip":"Не обещай чудес: скажи, что разведка с воздуха даст карту района, но техника нужна исправная."},{"id":"fact_30","title":"Лицензия радиолюбителя","text":"У тебя есть лицензия радиолюбителя: ты собираешь антенны и работаешь на любых доступных частотах.","tags":["связь","навык"],"tip":"Обещай поймать чужие сигналы: информация о других лагерях стоит дороже консервов."},{"id":"fact_31","title":"Тайник с припасами","text":"В гараже за городом у тебя спрятаны консервы, инструменты и две канистры бензина.","tags":["запасы","связи"],"tip":"Обменяй половину тайника на место в бункере, но не говори, где он: точное место — твоя страховка."},{"id":"fact_32","title":"Взлом замков","text":"Ты умеешь вскрывать замки и сейфы: откроешь склад, аптеку и оружейный ящик без ключа.","tags":["навык","прошлое"],"tip":"Предложи применить навык для группы, но подчеркни, что двери своих ты не вскрываешь."}]},"health":{"category":"health","label":"Здоровье","icon":"🩺","cards":[{"id":"heal_01","title":"Отличное здоровье","text":"Спортивный, тренированный, без единой хронической болезни. Восстанавливается быстро, к врачам не обращался годами.","tags":["здоровье","спорт"],"tip":"Не просто говори, что здоров: назови конкретно, что никогда не срываешь смену и не требуешь лекарств из общих запасов."},{"id":"heal_02","title":"Близорукость","text":"Минус шесть на оба глаза. В очках видит нормально, без них различает только силуэты на расстоянии пары шагов.","tags":["зрение","хроническое"],"tip":"Сразу уточни, есть ли в бункере запасные очки или линзы: если да, проблема снимается, и спор про зрение закрыт."},{"id":"heal_03","title":"Глух на одно ухо","text":"Слышит одним ухом: в шумном помещении разбирает речь с трудом и плохо определяет, откуда идёт звук.","tags":["слух","хроническое"],"tip":"Скажи, что работаешь без ограничений, но попроси место в тихом отсеке: честная просьба лучше скрытого дефекта."},{"id":"heal_04","title":"Аллергия на пыль","text":"В запылённом помещении начинает задыхаться и чихать. В чистом воздухе чувствует себя полностью здоровым.","tags":["аллергия","дыхание"],"tip":"Свяжи это с фильтрами: пока вентиляция работает, ты здоров, и это довод в пользу того, чтобы их чинили вовремя."},{"id":"heal_05","title":"Непереносимость лактозы","text":"Молоко и сыр вызывают у него боль и расстройство. Всё остальное переносит нормально и без ограничений.","tags":["пищеварение","диета"],"tip":"Скажи, что проблема касается только молочного: остальные запасы ты ешь как все, и дефицита из-за тебя не будет."},{"id":"heal_06","title":"Диабет первого типа","text":"Требует инсулина каждый день. Без препарата состояние ухудшается за сутки, а запасы зависят от аптечки бункера.","tags":["диабет","лекарства"],"tip":"Спроси прямо, что в аптечке и на сколько хватит: честный расчёт запаса лучше, чем обещание, что всё обойдётся."},{"id":"heal_07","title":"Диабет второго типа","text":"Держится на диете и таблетках. Сладкое и мучное нельзя, нагрузки и режим помогают не хуже лекарств.","tags":["диабет","диета"],"tip":"Предложи физическую работу: она снижает сахар без таблеток, и в бункере твоя диета совпадает с общей экономией."},{"id":"heal_08","title":"Бронхиальная астма","text":"Приступы случаются от пыли, дыма и нагрузки. Ингалятор снимает приступ за минуту, без него дышать нечем.","tags":["астма","дыхание"],"tip":"Уточни, есть ли ингалятор в аптечке: если да, ты работаешь наравне со всеми, а при пожаре тебе просто нельзя в дым."},{"id":"heal_09","title":"Эпилепсия под контролем","text":"Принимает препарат, приступов нет уже годы. Без таблеток приступы возвращаются, и это опасно на высоте и у огня.","tags":["эпилепсия","лекарства"],"tip":"Скажи, что под лечением ты полностью работоспособен: попроси только не ставить тебя на высоту и не экономить на препарате."},{"id":"heal_10","title":"Онкология в ремиссии","text":"Болезнь побеждена несколько лет назад, ремиссия стойкая. Нужны регулярные осмотры и внимательное отношение к нагрузкам.","tags":["онкология","ремиссия"],"tip":"Скажи прямо, что ремиссия длится годами и ты работаешь как все: честность здесь сильнее, чем попытка скрыть."},{"id":"heal_11","title":"Зависимость от алкоголя","text":"Год без спиртного, но тяга остаётся. В бункере с запасами и стрессом срыв возможен в любой момент.","tags":["зависимость","психика"],"tip":"Признай проблему и предложи правило: спирт только как антисептик и под учёт, а не как напиток. Так ты защищаешь группу."},{"id":"heal_12","title":"Зависимость от никотина","text":"Курит много лет и без сигарет становится раздражительным. На здоровье пока не жалуется, но кашель уже есть.","tags":["зависимость","дыхание"],"tip":"Скажи, что готов бросить, если запасов нет: в бункере дым вреден всем, и твоя готовность к отказу — реальный плюс."},{"id":"heal_13","title":"Клиническая депрессия","text":"Проходит терапию и держится ровно. В тяжёлые периоды теряет силы и нуждается в поддержке и препаратах.","tags":["психика","лекарства"],"tip":"Честно скажи, что знаешь свою болезнь и умеешь её держать: опытный пациент надёжнее того, кто впервые сломается."},{"id":"heal_14","title":"Панические атаки","text":"Приступы случаются внезапно: сердце колотится, воздуха не хватает. Длится минут десять и проходит без вреда.","tags":["психика","тревожность"],"tip":"Скажи, что научился пережидать приступ и работать дальше: это не болезнь тела, а состояние, и оно под контролем."},{"id":"heal_15","title":"Посттравматический стресс","text":"Пережил катастрофу и получил шрамы в памяти: громкие звуки и темнота возвращают его в тот день.","tags":["психика","опыт"],"tip":"Признай, что в бункере такие, как ты, будут у всех: ты единственный, кто уже знает, как это пережить."},{"id":"heal_16","title":"Язва желудка","text":"Обострения бывают от стресса и плохой еды. В спокойном режиме почти не беспокоит и лечится обычными средствами.","tags":["желудок","хроническое"],"tip":"Спроси, будет ли в бункере горячая еда: если да, обострение маловероятно, и ты работаешь наравне со всеми."},{"id":"heal_17","title":"Гипертония","text":"Давление скачет от волнения и соли. Таблетки держат его в норме, без них возможен криз и потеря сознания.","tags":["сердце","лекарства"],"tip":"Напомни, что давление у тебя под контролем годами: попроси только включить твои таблетки в список обязательных запасов."},{"id":"heal_18","title":"Аритмия","text":"Сердце бьётся неровно: при нагрузке случаются перебои и головокружение. Тяжёлый физический труд запрещён врачом.","tags":["сердце","ограничения"],"tip":"Предложи работу без перегрузок: точные и сидячие задачи ты выполняешь полностью, а бегать с мешками пусть идут другие."},{"id":"heal_19","title":"Грыжа позвоночника","text":"Болит спина при подъёме тяжестей и долгом стоянии. Ходит и работает нормально, но тяжести носить нельзя.","tags":["спина","ограничения"],"tip":"Скажи прямо, что тяжёлое не поднимаешь, и предложи работу по силам: честное ограничение лучше сорванной спины на второй день."},{"id":"heal_20","title":"Артрит","text":"Суставы болят в холод и сырость, пальцы теряют подвижность. В тёплом помещении состояние заметно лучше.","tags":["суставы","хроническое"],"tip":"Свяжи это с температурой в бункере: если будет тепло и сухо, ты работаешь как все, а холод тебе просто противопоказан."},{"id":"heal_21","title":"Хроническая мигрень","text":"Раз в месяц приступ с невыносимой болью и светобоязнью на сутки. В остальное время полностью работоспособен.","tags":["голова","хроническое"],"tip":"Скажи, что приступы редкие и предсказуемые: раз в месяц ты теряешь день, а не рабочую способность целиком."},{"id":"heal_22","title":"Апноэ во сне","text":"Во сне дышит с остановками и громко храпит. Сам не высыпается, а спать рядом с ним почти невозможно.","tags":["сон","дыхание"],"tip":"Честно предупреди, что храпишь, и предложи спать в дальнем отсеке: открытость тут стоит дороже, чем тихий обман."},{"id":"heal_23","title":"Слабый иммунитет","text":"Простужается от любого сквозняка и болеет долго. В замкнутом бункере это означает регулярные пропуски работы.","tags":["иммунитет","риск"],"tip":"Не отрицай слабость, но напомни, что бережёшься сам: ты не полезешь в холод без нужды и не заразишь остальных."},{"id":"heal_24","title":"Одна почка","text":"Живёт с одной почкой после операции. Работает нормально, но требует питьевого режима и запрета на тяжёлые нагрузки.","tags":["почки","ограничения"],"tip":"Скажи, что работоспособность полная: попроси только гарантированный доступ к воде, иначе твоё состояние ухудшится быстро."},{"id":"heal_25","title":"Хромота после перелома","text":"Нога срослась неудачно: ходит с заметной хромотой и быстро устаёт. Стоять и бегать долго не может.","tags":["ноги","ограничения"],"tip":"Предложи работу на одном месте: за столом, у приборов или на кухне ты полезнее, чем на бегу, и это честный расчёт."},{"id":"heal_26","title":"Тремор рук","text":"Руки мелко дрожат: точная работа требует усилий, а мелкие детали удержать трудно. Крупные операции даются легко.","tags":["руки","ограничения"],"tip":"Скажи, что берёшь на себя тяжёлые и грубые задачи: там дрожь не мешает, а точную работу отдай тем, у кого рука твёрдая."},{"id":"heal_27","title":"Потеря обоняния","text":"Не чувствует запахов после перенесённой болезни. Вкус еды почти не различает, но работает без ограничений.","tags":["обоняние","риск"],"tip":"Скажи честно, что не унюхаешь утечку газа: попроси напарника для проверок, и проблема перестаёт быть опасной."},{"id":"heal_28","title":"Последствия инсульта","text":"Пережил инсульт год назад: левая рука слабее, речь замедлена, но память и соображение полностью сохранны.","tags":["инсульт","ограничения"],"tip":"Не скрывай слабую руку и предложи работу головой: расчёт, учёт и планирование ты делаешь лучше многих здоровых."},{"id":"heal_29","title":"Анемия","text":"Низкий гемоглобин: быстро устаёт, кружится голова, на холоде руки немеют. Лечится питанием и препаратами железа.","tags":["кровь","хроническое"],"tip":"Спроси про рацион: если в бункере будет мясо или железо в таблетках, ты работаешь как все, и это решаемый вопрос."},{"id":"heal_30","title":"Туберкулёз в открытой форме","text":"Активная форма болезни: кашляет и заразен для окружающих. Лечение долгое, требует изоляции и постоянных препаратов.","tags":["инфекция","опасность"],"tip":"Не скрывай диагноз: предложи отдельный отсек и маску. Скрытая инфекция убьёт бункер, и это единственный честный аргумент."}]},"help":{"phases":[{"id":"lobby","title":"Лобби и настройки","short":"Соберите комнату и задайте правила.","text":"Хост создаёт комнату и получает код, остальные подключаются по нему с телефона или ноутбука. В лобби хост задаёт число мест в бункере, длительность фаз, число раундов и режим спец. возможностей.","tips":["Проверьте связь до старта: обновите страницу, если игрок висит в списке без отметки готовности.","Договоритесь о темпе: с коротким таймером партия на восемь человек идёт около получаса.","Скопируйте код комнаты в общий чат, чтобы никто не вводил его вручную по буквам."]},{"id":"reveal","title":"Раскрытие характеристик","short":"Открой карты и объясни, чем полезен.","text":"В каждом раунде ты открываешь часть характеристик: лимит зависит от числа игроков и указан над твоим персонажем. В первом раунде первым всегда идёт профессия. Всё, что не открыто, остаётся скрытым до конца партии.","tips":["Не читай карту дословно: сразу говори, какую проблему бункера она решает.","Слабую карту раскрывай вместе с сильной и объясняй, чем ты компенсируешь недостаток.","Следи за счётчиком раскрытий: открытую карту уже нельзя спрятать обратно."]},{"id":"discussion","title":"Обсуждение","short":"Спорьте, аргументируйте, ищите союзников.","text":"Фаза свободного спора: кто полезнее, а кто балласт. Здесь решается исход партии, а голосование лишь фиксирует настроение зала. Задавай вопросы по открытым картам и требуй конкретных обещаний.","tips":["Задавай прямые вопросы: «Что ты будешь делать в бункере в первый день?» — общие ответы видно сразу.","Собирай союзников заранее: два-три голоса, договорённых до голосования, решают исход.","Не молчи: игрок, который не участвует в споре, первым становится кандидатом на изгнание."]},{"id":"voting","title":"Голосование","short":"Выберите, кто покинет лагерь.","text":"Все игроки с правом голоса выбирают, кого изгнать. Если игрок не успел проголосовать, его голос автоматически уходит против него самого. Воздержаться можно только в первом раунде и только при большинстве таких голосов.","tips":["Смотри не только на карты, но и на поведение: агрессивный спорщик опаснее слабой характеристики.","Голосуй ближе к концу: увидишь расклад и не потратишь голос на того, кого изгонят и без тебя.","Следи за таймером: окно голосования короткое, а пропуск голоса бьёт по тебе же."]},{"id":"defense","title":"Оправдание и повторное голосование","short":"Последнее слово перед изгнанием.","text":"Если против игрока набралось семьдесят процентов голосов, его изгоняют сразу. В остальных случаях кандидаты произносят оправдательные речи, после чего проходит повторное голосование, а изгнанный получает прощальное слово.","tips":["Говори коротко и по делу: три конкретных довода работают лучше долгой истории жизни.","Не оправдывайся, а предлагай: назови задачу, которую возьмёшь на себя в бункере.","При ничьей в первом раунде никто не изгоняется, а в следующих уходят все лидеры — учитывай это."]},{"id":"finale","title":"Финал","short":"Итог: кто вошёл в бункер, кто остался снаружи.","text":"Игра заканчивается, когда все места в бункере заняты. Вы увидите итоговый состав, срок изоляции, запас еды и лог событий партии. Оставшиеся за пределами бункера считаются погибшими.","tips":["Разберите партию сразу: одна фраза о том, где вы ошиблись, делает следующую игру интереснее.","Попроси хоста сохранить лог: по нему видно, какие аргументы действительно сработали.","Сравните запас еды со сроком катастрофы: так вы поймёте, кого стоило брать в бункер."]}],"faq":[{"q":"Сколько мест в бункере?","a":"По умолчанию — половина игроков с округлением вниз: 6 игроков → 3 места, 8 → 4, 12 → 6. Хост может задать фиксированное число в настройках комнаты."},{"q":"Сколько раундов длится партия?","a":"По умолчанию не больше семи раундов, но игра заканчивается раньше, если все места в бункере уже заняты. Точное число раундов задаёт хост."},{"q":"Что делать, если не успел проголосовать?","a":"Твой голос автоматически уходит против тебя самого — так работает правило. Следи за таймером: на голосование обычно даётся пятнадцать секунд."},{"q":"Можно ли пропустить голосование?","a":"Да, кнопкой воздержания, но только в первом раунде и только если так проголосует большинство: тогда раунд закрывается без изгнания. В остальных раундах воздержание ничего не решает."},{"q":"Что такое спец. возможность?","a":"Это разовое действие из твоей карты «Спец. возможность»: вскрыть чужую карту, удвоить голос, вернуть изгнанного. Применить её можно один раз за партию и только после того, как ты раскрыл эту карту."},{"q":"Что видят другие игроки?","a":"Только те карты, которые ты открыл сам. Закрытые характеристики, твои личные заметки и неиспользованная спец. возможность скрыты от остальных."},{"q":"Как присоединиться по коду?","a":"Открой тот же адрес игры, введи код комнаты, укажи имя и нажми «Войти». Код показан в лобби у хоста и копируется одной кнопкой."},{"q":"Что если игрок вышел из игры?","a":"Он остаётся в списке отключившимся: характеристики сохраняются, но он не голосует и не раскрывает карты. Хост решает, ждать его или продолжать партию без него."},{"q":"Сколько карт открывается за раунд?","a":"Зависит от числа игроков: при шести — 3/3/2, при семи-восьми — 3/2/2 и далее по одной, при девяти-десяти — 3/2/1 и далее по одной. Лимит этого раунда показан над твоим персонажем."},{"q":"Что происходит с изгнанным?","a":"Он уходит во временный лагерь: раскрывать карты и голосовать больше не может, но видит партию и может вернуться, если кто-то применит спец. возможность возврата."},{"q":"Как изгоняют без оправданий?","a":"Если против игрока набралось семьдесят процентов голосов от числа голосующих, его исключают сразу. В остальных случаях сначала идут оправдательные речи, потом повторное голосование."},{"q":"Что будет при равенстве голосов?","a":"В первом раунде ничья оставляет всех на местах, а в следующих изгоняются все, кто делит первое место. Поэтому лишний голос за слабого кандидата бывает опасен."},{"q":"Что делать, если не понял карту?","a":"Открой справку: у каждой карты есть подсказка по аргументации, а незнакомые термины объяснены в глоссарии ниже."}],"glossary":[{"term":"Временный лагерь","definition":"Место перед бункером, где находятся все выжившие до конца игры."},{"term":"Бункер","definition":"Убежище, в которое в финале попадает только часть игроков: число мест определяет хост."},{"term":"Место в бункере","definition":"Слот в финальном составе. Игра заканчивается, когда все места заняты."},{"term":"Раунд","definition":"Один цикл игры: раскрытие карт, обсуждение, голосование и оправдания."},{"term":"Раскрытие","definition":"Открытие характеристики для всех игроков. Открытую карту уже нельзя спрятать."},{"term":"Изгнание","definition":"Решение большинства: игрок покидает бункер и уходит во временный лагерь."},{"term":"Оправдательная речь","definition":"Короткое выступление кандидата на изгнание перед повторным голосованием."},{"term":"Спец. возможность","definition":"Разовое действие из карты персонажа, которое можно применить один раз за партию."},{"term":"Воздержание","definition":"Голос против всех: доступен только в первом раунде и только при большинстве таких голосов."},{"term":"Хост","definition":"Создатель комнаты: задаёт настройки, время фаз и запускает игру."},{"term":"Лог событий","definition":"Хроника партии: изгнания, возвраты и применения спец. возможностей."},{"term":"Катастрофа","definition":"Глобальное событие, которое задаёт условия выживания и срок изоляции."},{"term":"Угроза","definition":"Опасность, которую создаёт катастрофа: радиация, холод, голод или болезни."}]},"hobbies":{"category":"hobby","label":"Хобби","icon":"🎲","cards":[{"id":"hobby_01","title":"Радиолюбитель","text":"Паяет схемы и собирает приёмники из старых деталей. Может поймать сигнал на самодельную антенну из провода.","tags":["связь","техника"],"tip":"Напомни про связь снаружи: пока другие молчат в эфире, ты собираешь приёмник из того, что лежит в кладовке."},{"id":"hobby_02","title":"Аквариумист","text":"Годами держит замкнутый водоём с растениями и рыбой. Знает, как сохранить воду живой без химии и фильтров.","tags":["вода","экосистема"],"tip":"Свяжи это с водой и едой: ты умеешь держать замкнутую систему годами, а бункер — это большой аквариум."},{"id":"hobby_03","title":"Садовод-любитель","text":"Выращивает овощи и зелень даже на балконе. Знает, сколько нужно света и как получить урожай в тесноте.","tags":["еда","растения"],"tip":"Предложи разбить огород в бункере: ты уже делал это на балконе, а значит, справишься и в подвале."},{"id":"hobby_04","title":"Домашние закатки","text":"Консервирует всё, что растёт: огурцы, помидоры, варенье. Знает, как хранить еду годами без холодильника.","tags":["еда","запасы"],"tip":"Спроси, как хранить запасы: без закаток и стерилизации еда в бункере сгниёт задолго до конца срока."},{"id":"hobby_05","title":"Домашнее пивоварение","text":"Варит пиво в квартире и разбирается в брожении. Умеет делать напиток из зерна и трав без специального оборудования.","tags":["еда","брожение"],"tip":"Продай не пиво, а умение: брожение даёт и напиток, и уксус, и консервант, а это уже производство."},{"id":"hobby_06","title":"Рыбалка","text":"Ловит рыбу в любую погоду и знает, где она стоит. Может сделать снасть из лески и булавки.","tags":["еда","вода"],"tip":"Напомни про белок: если рядом есть водоём, ты единственный, кто вернётся с настоящей едой, а не с надеждой."},{"id":"hobby_07","title":"Тихая охота","text":"Собирает грибы и знает их наизусть. Отличает съедобный от ядовитого и умеет сушить добычу на зиму.","tags":["еда","лес"],"tip":"Скажи, что различаешь грибы без справочника: одна ошибка здесь стоит жизни, и в этом ты надёжнее любого."},{"id":"hobby_08","title":"Турист-походник","text":"Ходит в походы годами: ставит палатку, разводит огонь в дождь и находит дорогу без карты и компаса.","tags":["выживание","поход"],"tip":"Предложи себя для вылазок: ты умеешь идти, ночевать в холоде и возвращаться, а это редкий навык в бункере."},{"id":"hobby_09","title":"Скалолазание","text":"Лазает по стенам и умеет страховаться. Спокойно работает на высоте, где остальные боятся даже смотреть.","tags":["высота","ловкость"],"tip":"Напомни про высотные работы: вентиляция, трубы и стены бункера требуют того, кто не боится упасть."},{"id":"hobby_10","title":"Спелеология","text":"Исследует пещеры и узкие ходы. Умеет работать в темноте и тесноте, где нет ни света, ни воздуха.","tags":["теснота","темнота"],"tip":"Свяжи с бункером напрямую: замкнутое пространство и темнота для тебя привычны, а для остальных это стресс."},{"id":"hobby_11","title":"Стрельба из лука","text":"Стреляет точно на тридцать шагов и делает стрелы сам. Тихое оружие, которое не требует пороха и патронов.","tags":["оружие","охота"],"tip":"Скажи, что патроны кончатся, а стрелы можно сделать заново: тихая охота и защита без взрывчатки — это надолго."},{"id":"hobby_12","title":"Страйкбол","text":"Играет в командные бои и знает тактику: как двигаться группой, прикрывать друг друга и занимать позиции.","tags":["тактика","защита"],"tip":"Предложи себя в охрану: ты умеешь действовать в команде и понимаешь, как держать периметр и не терять друг друга."},{"id":"hobby_13","title":"Сборка моделей","text":"Клеит и красит модели самолётов и техники. Работает с мелочами часами и не теряет терпения.","tags":["моторика","терпение"],"tip":"Переведи в навык: терпение и мелкая моторика нужны для ремонта приборов, а не только для моделей."},{"id":"hobby_14","title":"Резьба по дереву","text":"Вырезает из дерева фигуры и посуду. Умеет работать ножом точно и делает нужные вещи из любой чурки.","tags":["дерево","ремесло"],"tip":"Скажи, что из дерева можно сделать ложку, ручку для инструмента и крепление: без этого в бункере всё придётся держать руками."},{"id":"hobby_15","title":"Гончарное дело","text":"Лепит и обжигает посуду. Знает, где взять глину и как сделать посуду, которая не боится огня.","tags":["глина","ремесло"],"tip":"Напомни, что посуда бьётся: в бункере с ограниченным запасом чашек гончар — это непрерывное производство."},{"id":"hobby_16","title":"Кожевенное дело","text":"Шьёт из кожи ремни, обувь и сумки. Умеет выделывать шкуру и делать прочные вещи без фабрики.","tags":["кожа","ремонт"],"tip":"Предложи ремонт обуви: без крепкой обуви любая вылазка заканчивается за первый час, а ты её продлеваешь."},{"id":"hobby_17","title":"Вязание","text":"Вяжет свитера, шапки и носки из любой пряжи. Может распустить старую вещь и связать из неё новую.","tags":["тепло","одежда"],"tip":"Свяжи это с теплом: носки и шапки в холодном бункере нужны всем, а пряжу можно добыть из старой одежды."},{"id":"hobby_18","title":"Игра на гитаре","text":"Играет и поёт с детства, знает сотни песен. Умеет держать настроение группы вечером без электричества.","tags":["музыка","настроение"],"tip":"Напомни, что людям нужны вечера: без музыки и песен в замкнутом бункере люди гаснут за пару месяцев."},{"id":"hobby_19","title":"Шахматы","text":"Играет годами и считает варианты на несколько ходов вперёд. Привык думать, прежде чем делать ход.","tags":["логика","планирование"],"tip":"Переведи игру в характер: ты привык считать последствия, а в бункере поспешное решение стоит жизни."},{"id":"hobby_20","title":"Головоломки и кроссворды","text":"Разгадывает сложные задачи ради удовольствия. Держит память в форме и любит искать нестандартные решения.","tags":["логика","память"],"tip":"Скажи, что умеешь решать задачи без инструкции: в бункере половина проблем именно такие."},{"id":"hobby_21","title":"Йога","text":"Практикует годами: держит равновесие, растяжку и дыхание. Умеет успокаивать себя без таблеток и врача.","tags":["здоровье","спокойствие"],"tip":"Продай дыхание и спокойствие: ты умеешь снимать стресс у себя и можешь научить этому остальных."},{"id":"hobby_22","title":"Медитация","text":"Умеет сидеть в тишине часами и не сходить с ума от однообразия. Контролирует тревогу без всяких средств.","tags":["психика","спокойствие"],"tip":"Напомни про замкнутое пространство: ты выдерживаешь монотонность там, где другие ломаются через месяц."},{"id":"hobby_23","title":"Астрономия","text":"Знает звёздное небо и умеет определять время и направление по светилам без приборов и карт.","tags":["навигация","наука"],"tip":"Скажи, что компас и часы в бункере сломаются: ты определяешь направление по небу и не потеряешься."},{"id":"hobby_24","title":"Ботаника","text":"Собирает и определяет растения, знает, какое лечит, какое кормит, а какое лучше не трогать вовсе.","tags":["растения","медицина"],"tip":"Предложи искать еду и лекарства снаружи: ты отличаешь полезное растение от ядовитого и не отравишь группу."},{"id":"hobby_25","title":"Энтомология","text":"Изучает насекомых и знает, каких можно есть, чем ловить вредителей и как использовать их в хозяйстве.","tags":["насекомые","еда"],"tip":"Напомни про белок из насекомых: когда мясо кончится, ты знаешь, что в округе съедобно, а другие нет."},{"id":"hobby_26","title":"Коллекция ножей","text":"Собирает ножи годами и умеет точить любой клинок до бритвенной остроты. Разбирается в сталях и рукоятях.","tags":["инструмент","металл"],"tip":"Скажи, что тупой нож опаснее острого: ты поддержишь инструмент группы в рабочем состоянии всю дорогу."},{"id":"hobby_27","title":"Радиоуправляемые модели","text":"Собирает и настраивает дроны и машинки. Умеет вести аппарат по камере и чинить его после падений.","tags":["техника","разведка"],"tip":"Предложи разведку: аппарат с камерой может осмотреть подходы к бункеру, и никто не будет рисковать головой."},{"id":"hobby_28","title":"Травничество","text":"Сушит травы и делает настои от простуды, бессонницы и боли в животе. Помнит, что и когда собирать.","tags":["травы","медицина"],"tip":"Уточни запас лекарств: если аптечка пуста, травы остаются единственным средством, и знаешь их только ты."},{"id":"hobby_29","title":"Металлопоиск","text":"Ходит с металлоискателем по старым местам и знает, где искать металл, инструменты и брошенную технику.","tags":["металл","поиск"],"tip":"Предложи поиск металла снаружи: бункеру нужны инструменты и запчасти, а ты знаешь, где их найти."},{"id":"hobby_30","title":"Разведение голубей","text":"Держит голубей годами и знает, как они находят дорогу домой даже за десятки километров.","tags":["связь","птицы"],"tip":"Напомни, что это живая связь: голубь донесёт записку туда, где радио уже не берёт."}]},"luggage":{"category":"luggage","label":"Крупный инвентарь","icon":"🧰","cards":[{"id":"lugg_01","title":"Дизель-генератор","text":"Тяжёлый генератор на дизеле: даёт свет и питание для инструментов, пока в баке есть топливо.","tags":["энергия","техника"],"tip":"Требуй место под генератор и запас солярки: если ты умеешь его обслуживать, без тебя бункер останется без света."},{"id":"lugg_02","title":"Полевой медблок","text":"Разборный медицинский набор с операционным столом, шовным материалом и запасом антибиотиков.","tags":["медицина","запасы"],"tip":"Предложи развернуть его в отдельной комнате и сам займись стерилизацией: без этого медик не справится."},{"id":"lugg_03","title":"Ящик сухпайков","text":"Двадцать четыре армейских пайка в вакуумной упаковке: калорий хватит на месяц экономной жизни.","tags":["еда","запасы"],"tip":"Не раздавай пайки сразу: часть обменяй на место в команде и у печи, остальное держи как козырь."},{"id":"lugg_04","title":"Сварочный аппарат","text":"Аппарат с баллоном и маской: варит металл, режет петли и закрывает пробоины в переборках.","tags":["техника","ремонт"],"tip":"Заяви, что герметизация бункера без сварки невозможна, и предложи себя в пару к любому инженеру."},{"id":"lugg_05","title":"Бочка дизтоплива","text":"Двести литров топлива в герметичной бочке: генератору хватит на несколько месяцев работы.","tags":["топливо","запасы"],"tip":"Держи объём в секрете до торга: топливо быстро станет валютой, и за долю тебе предложат место."},{"id":"lugg_06","title":"Банк семян","text":"Коробка с семенами овощей и зерновых в сухих пакетах: при свете и воде даст первый урожай.","tags":["еда","растения"],"tip":"Подчеркни, что через год все запасы кончатся, а твои семена — единственный источник свежей еды."},{"id":"lugg_07","title":"Разборная печь","text":"Печь из чугунных секций: греет комнату, сушит одежду и готовит еду на дровах и угле.","tags":["тепло","быт"],"tip":"Обещай собрать её в первую неделю и поставить у общего зала — тогда к твоей печи придут все."},{"id":"lugg_08","title":"Ящик инструментов","text":"Полный набор ключей, отвёрток, пил и свёрл в металлическом ящике, включая домкрат.","tags":["инструменты","ремонт"],"tip":"Скажи, что любой ремонт начинается с твоего ящика, и предложи вести учёт выдачи инструментов."},{"id":"lugg_09","title":"Канистра спирта","text":"Двадцать литров технического спирта: антисептик, растворитель, топливо и повод для торга.","tags":["медицина","химия"],"tip":"Не уточняй, что спирт технический: продай его как медицинский запас, а часть оставь на обмен."},{"id":"lugg_10","title":"Радиостанция","text":"Армейская станция с антенной на десять километров: ловит чужие переговоры и передаёт свои.","tags":["связь","техника"],"tip":"Скажи, что через тебя бункер узнает о других лагерях, и предложи слушать эфир по ночам."},{"id":"lugg_11","title":"Надувная лодка","text":"Резиновая лодка на четырёх человек с вёслами: переправа по затопленным уровням и вылазки.","tags":["транспорт","вода"],"tip":"Предложи использовать её для вылазок за припасами: без лодки часть маршрутов просто недоступна."},{"id":"lugg_12","title":"Армейская палатка","text":"Большая палатка с тентом и полом: быстрое жильё на поверхности и карантинная зона у входа.","tags":["быт","укрытие"],"tip":"Придумай ей задачу внутри бункера: карантин, мастерская или склад, иначе тебя посчитают балластом."},{"id":"lugg_13","title":"Ящик учебников","text":"Учебники по физике, химии, медицине и ремонту с пометками на полях: знания без электричества.","tags":["знания","книги"],"tip":"Напомни, что книги не портятся и не кончаются, а один справочник может спасти жизнь зимой."},{"id":"lugg_14","title":"Швейная машинка","text":"Ручная машинка с набором игл и ниток: чинит одежду, шьёт брезент и ремонтирует фильтрующие мешки.","tags":["быт","ремонт"],"tip":"Заметь, что одежда изнашивается быстрее еды, и предложи взять на себя всю починку вещей в бункере."},{"id":"lugg_15","title":"Кузнечный горн","text":"Малый горн с мехами и наковальней: переплавляет металл, делает ножи, гвозди и крепёж.","tags":["металл","ремесло"],"tip":"Обещай наладить производство инструментов из хлама: редкий навык, который трудно заменить кем-то другим."},{"id":"lugg_16","title":"Водоочистная станция","text":"Фильтры и насос на сто литров в сутки: делают техническую воду пригодной для питья.","tags":["вода","техника"],"tip":"Скажи прямо: без очистки воды бункер продержится неделю, и место рядом с фильтрами дороже еды."},{"id":"lugg_17","title":"Оружейный сейф","text":"Запертый сейф с четырьмя карабинами и патронами: оружие для охраны шлюза и вылазок.","tags":["оружие","защита"],"tip":"Не раздавай оружие даром: предложи выдавать его идущим в разведку, а ключ оставь себе."},{"id":"lugg_18","title":"Солнечная панель","text":"Складная панель на триста ватт с контроллером: даёт свет и зарядку в ясные дни наверху.","tags":["энергия","техника"],"tip":"Честно скажи, что под землёй панель бесполезна, но на вылазках она питает дозиметр и рации."},{"id":"lugg_19","title":"Бетономешалка","text":"Ручная мешалка с баком: замешивает раствор для перекрытий, полов и заделки трещин в стенах.","tags":["стройка","ремонт"],"tip":"Предложи укреплять бункер своими руками: ты готов смешивать раствор, таскать блоки и заливать полы."},{"id":"lugg_20","title":"Тяговый аккумулятор","text":"Батарея на двести ампер-часов: запасает энергию генератора и питает приборы ночью.","tags":["энергия","запасы"],"tip":"Объясни, что ночью генератор можно глушить: тишина и экономия топлива — твой главный аргумент."},{"id":"lugg_21","title":"Набор химика","text":"Реактивы, колбы и весы: анализирует воду, делает антисептик, удобрения и дымовые шашки.","tags":["химия","наука"],"tip":"Пообещай проверять воду и воздух на яды: без анализа все риски останутся только догадками."},{"id":"lugg_22","title":"Барабан кабеля","text":"Триста метров медного кабеля и разъёмы: проводка, освещение и связь между отсеками.","tags":["энергия","связь"],"tip":"Скажи, что освещение дальних комнат зависит от твоего кабеля, и предложи себя в электрики."},{"id":"lugg_23","title":"Баллон пропана","text":"Сорокалитровый баллон с редуктором и горелкой: готовка и обогрев без дров и дыма.","tags":["тепло","топливо"],"tip":"Держи баллон при себе и напомни, что открытый огонь в бункере запрещён, а горелка — исключение."},{"id":"lugg_24","title":"Газовый холодильник","text":"Холодильник на пропане: хранит мясо, лекарства и вскрытые банки без электричества.","tags":["еда","быт"],"tip":"Напомни, что испорченная еда убивает быстрее голода, и предложи вести учёт скоропортящихся запасов."},{"id":"lugg_25","title":"Ручной насос","text":"Насос с длинным шлангом: поднимает воду из нижних уровней и откачивает затопленные отсеки.","tags":["вода","техника"],"tip":"Предложи дежурить у насоса: если вода пойдёт вниз, откачивать её будет некому, кроме тебя."},{"id":"lugg_26","title":"Мешки с удобрением","text":"Шесть мешков с азотными и калийными удобрениями: урожай на слабом свете и обмен на еду.","tags":["растения","запасы"],"tip":"Скажи, что удобрения нужны и для огорода, и для пороха, — и попроси место в команде под них."},{"id":"lugg_27","title":"Мотоблок","text":"Ручной мотоблок с плугом: обрабатывает землю на поверхности, если бункер доживёт до весны.","tags":["растения","техника"],"tip":"Обещай вспахать поле у входа и вырастить еду: тем, кто думает про год вперёд, твоя карта нужна."},{"id":"lugg_28","title":"Бочка мёда","text":"Восемьдесят литров мёда в закрытой бочке: еда, антисептик и обменный товар на годы.","tags":["еда","медицина"],"tip":"Не раскрывай объём сразу: часть мёда обменяй на место у печи, остальное держи в тайнике."},{"id":"lugg_29","title":"Компрессор","text":"Электрический компрессор с ресивером: накачивает баллоны, красит стены и питает пневмоинструмент.","tags":["техника","ремонт"],"tip":"Предложи чинить фильтры и красить переборки: пневмоинструмент делает эту работу втрое быстрее."},{"id":"lugg_30","title":"Перегонный куб","text":"Медный куб с трубками и змеевиком: гонит спирт, чистит воду и разделяет химические смеси.","tags":["химия","вода"],"tip":"Продай его как источник чистого спирта для медицины и обмена: редкая и очень нужная вещь."}]},"phobias":{"category":"phobia","label":"Фобия","icon":"😱","cards":[{"id":"phob_01","title":"Клаустрофобия","text":"В замкнутых помещениях тебя накрывает паника: перехватывает дыхание, трясутся руки, хочется немедленно выйти наружу.","tags":["психика","паника"],"tip":"Признайся сразу и предложи выход: ты берёшь верхние ярусы и дежурства у выхода, а в тесные отсеки ходит напарник."},{"id":"phob_02","title":"Никтофобия","text":"Боишься темноты: без света не можешь уснуть и слышишь в тишине шаги, которых на самом деле нет.","tags":["психика","сон"],"tip":"Проси место рядом с аварийной лампой и предложи взять на себя вечерние обходы — так страх станет твоей работой."},{"id":"phob_03","title":"Мизофобия","text":"Не выносишь грязь: чужие руки, общие кружки и запах сырости вызывают у тебя тошноту и дрожь.","tags":["гигиена","психика"],"tip":"Сделай страх пользой: ты и есть тот, кто будет кипятить воду, мыть посуду и следить за чистотой отсеков."},{"id":"phob_04","title":"Гемофобия","text":"При виде крови ты бледнеешь и падаешь в обморок — даже когда кровь чужая и твоя помощь нужна прямо сейчас.","tags":["медицина","психика"],"tip":"Скажи прямо, что теряешь сознание от вида крови, и предложи взять всё, кроме операций: воду, кухню, склад."},{"id":"phob_05","title":"Айхмофобия","text":"Панически боишься острых предметов: ножей, игл, осколков. Работа с ними заканчивается дрожью в руках.","tags":["психика","инструменты"],"tip":"Проси замену инструмента: вместо ножа — кусачки и пила, а разделку туш оставь тому, кто не вздрагивает."},{"id":"phob_06","title":"Пирофобия","text":"Огонь для тебя угроза: ты не подходишь к печам и горелкам и не можешь заставить себя разжечь спичку.","tags":["огонь","психика"],"tip":"Честно скажи, что печь и костёр не твои, но возьми то, что не горит: воду, склад, наблюдение за приборами."},{"id":"phob_07","title":"Танатофобия","text":"Ты паникуешь при любой мысли о смерти: вид покойника выбивает тебя из строя на несколько суток.","tags":["психика","смерть"],"tip":"Не прячься: признай страх и предложи не участвовать в захоронениях, взяв взамен самую рутинную работу."},{"id":"phob_08","title":"Социофобия","text":"Большие компании тебя выматывают: в общем зале ты говоришь шёпотом и стараешься сесть у самой стены.","tags":["психика","общение"],"tip":"Переведи это в пользу: ты спокойно работаешь один в мастерской или на кухне, пока остальные спорят."},{"id":"phob_09","title":"Арахнофобия","text":"Пауки вызывают у тебя ужас: ты не можешь ни спать, ни есть, если знаешь, что рядом есть паутина.","tags":["насекомые","психика"],"tip":"Попроси, чтобы осмотр углов и вентиляции закрепили за другим, а сам возьми уборку открытых зон и склада."},{"id":"phob_10","title":"Энтомофобия","text":"Любые насекомые, включая муравьёв и моль, вызывают у тебя тошноту и желание немедленно бежать.","tags":["насекомые","гигиена"],"tip":"Заяви, что дезинсекция не твоя задача, а взамен следи за чистотой продуктов и герметичностью мешков."},{"id":"phob_11","title":"Радиофобия","text":"Ты боишься радиации настолько, что не подходишь к дозиметру: даже шкала прибора вызывает панику.","tags":["радиация","психика"],"tip":"Договорись, что замеры делает другой, а ты ведёшь журнал показаний в отдалённой комнате — данные нужны всем."},{"id":"phob_12","title":"Криофобия","text":"Холод для тебя пытка: при низкой температуре ты цепенеешь, а руки отказываются работать уже через минуту.","tags":["холод","психика"],"tip":"Проси место у печи или генератора и бери дежурства в тёплые часы: в холодных отсеках от тебя мало толку."},{"id":"phob_13","title":"Термофобия","text":"Жара вызывает у тебя обмороки: в душном помещении ты теряешь силы быстрее, чем кто-либо в команде.","tags":["жара","психика"],"tip":"Возьми ночные смены у вентиляции, когда в бункере прохладнее, и попроси не ставить тебя к котлам."},{"id":"phob_14","title":"Аутофобия","text":"Ты не переносишь одиночества: закрытая дверь на час превращает тебя в дрожащего и бесполезного человека.","tags":["психика","общение"],"tip":"Предложи работу в паре: пусть напарник заходит каждые полчаса, а ты возьмёшь самую шумную вахту."},{"id":"phob_15","title":"Фонофобия","text":"Громкие звуки, особенно внезапные, вызывают у тебя панику и звон в ушах на несколько часов.","tags":["звук","психика"],"tip":"Договорись, что тебя предупреждают о сварке и запуске генератора, и возьми тихие задачи: шитьё и учёт."},{"id":"phob_16","title":"Сомнифобия","text":"Ты боишься засыпать: во сне ты беспомощен, поэтому дежуришь до тех пор, пока не свалишься от усталости.","tags":["сон","психика"],"tip":"Проси короткие смены днём и партнёра рядом на время сна — иначе через неделю станешь обузой для всех."},{"id":"phob_17","title":"Нозофобия","text":"Ты одержим страхом заболеть: любое покашливание соседа воспринимаешь как начало смертельной эпидемии.","tags":["болезни","гигиена"],"tip":"Направь тревогу в дело: предложи карантинные правила, маски и кипячение посуды — команда скажет спасибо."},{"id":"phob_18","title":"Фармакофобия","text":"Ты боишься таблеток и уколов: при одной мысли об инъекции у тебя начинаются дрожь и тошнота.","tags":["медицина","психика"],"tip":"Предупреди медика заранее и обсуди альтернативы: отвары, компрессы и наружные средства вместо таблеток."},{"id":"phob_19","title":"Токсикофобия","text":"Ты боишься любых ядов и химии: не открываешь канистры, не смешиваешь растворы и не чистишь фильтры.","tags":["химия","психика"],"tip":"Скажи прямо, что химия не твоя, и предложи взять механику: воду, дерево, металл и ремонт одежды."},{"id":"phob_20","title":"Гелиофобия","text":"Ты не выносишь яркого солнца: открытое небо и резкий свет вызывают у тебя головную боль и панику.","tags":["солнце","психика"],"tip":"Просись в ночные вахты и подземные работы — там ты полезен, а на поверхности тебя заменит любой другой."},{"id":"phob_21","title":"Астрафобия","text":"Грозы и раскаты грома вгоняют тебя в ступор: ты забиваешься в угол и не можешь ничего делать.","tags":["погода","психика"],"tip":"Проси на время грозы простую задачу в глубине бункера и заранее договорись, кто подменит тебя на посту."},{"id":"phob_22","title":"Хронофобия","text":"Ты боишься часов и календарей: вид даты напоминает, сколько времени уже потеряно, и ты срываешься.","tags":["время","психика"],"tip":"Обменяй это на пользу: расписание пусть ведёт другой, а ты отвечаешь за воду, склад и порядок в отсеках."},{"id":"phob_23","title":"Гидрофобия","text":"Глубина и тёмная вода тебя пугают: ты не войдёшь в затопленный отсек даже по колено.","tags":["вода","психика"],"tip":"Честно назови границу и предложи работу на сухих уровнях: насосы, шланги и контроль уровня воды."},{"id":"phob_24","title":"Акрофобия","text":"Высота лишает тебя воли: на лестнице или крыше ты вцепляешься в опору и не можешь разжать руки.","tags":["высота","психика"],"tip":"Проси нижние ярусы и ремонт на земле, а осмотр крыши и шахт оставь тем, кто не боится падать."},{"id":"phob_25","title":"Трипофобия","text":"Скопления мелких отверстий, ржавых пятен и трещин вызывают у тебя зуд и приступы тошноты.","tags":["психика","ремонт"],"tip":"Не спорь о пустяках, а предложи перекрыть проблемные стены панелями и краской — заодно займёшься отделкой."},{"id":"phob_26","title":"Агорафобия","text":"Открытое пространство тебя пугает: после месяцев под землёй выход наружу для тебя почти невозможен.","tags":["психика","замкнутость"],"tip":"Сразу скажи, что наружу не пойдёшь, и предложи остаться за старшего внутри: склад, кухня, ремонт, шлюз."}]},"professions":{"category":"profession","label":"Профессия","icon":"🛠","cards":[{"id":"prof_01","title":"Хирург","text":"Оперирует в полевых условиях, знает анатомию и умеет стерилизовать инструменты подручным.","tags":["медицина","наука"],"tip":"Спроси, есть ли в бункере медпункт: если да, ты закрываешь главную уязвимость, и это твой козырь против любого со здоровьем."},{"id":"prof_02","title":"Инженер-электрик","text":"Чинит генераторы и проводку, считает нагрузку на сеть и собирает освещение из списанных деталей.","tags":["техника","энергия"],"tip":"Попроси назвать источник энергии в бункере: без тока убежище превращается в холодную бетонную коробку, и это твой аргумент."},{"id":"prof_03","title":"Агроном","text":"Знает, как вырастить еду на мёртвой земле: подбирает культуры, сроки посева и удобрения без магазина.","tags":["еда","наука"],"tip":"Уточни запасы еды в бункере: если их мало, ты превращаешь кладовую в огород, и крыть этот довод нечем."},{"id":"prof_04","title":"Сантехник","text":"Разводит трубы, чинит насосы и находит утечку по звуку. Без него вода в бункере кончится быстро.","tags":["вода","техника"],"tip":"Спроси про воду и канализацию: в замкнутом убежище это ломается первым, а починить это умеешь только ты."},{"id":"prof_05","title":"Химик-технолог","text":"Считает реакции в уме, делает мыло и антисептик, очищает воду. Осторожен с тем, что нельзя смешивать.","tags":["наука","вода"],"tip":"Предложи проверить состав воды и воздуха: ты единственный, кто отличит безопасное от отравы без приборов."},{"id":"prof_06","title":"Ветеринар","text":"Лечит животных, а заодно умеет зашивать раны и принимать роды, когда рядом нет людей с дипломом.","tags":["медицина","животные"],"tip":"Напомни, что в бункере могут быть животные и роды: твои навыки шире, чем кажется, и довод «ты не медик» ломается."},{"id":"prof_07","title":"Кузнец","text":"Гнёт металл молотом, делает ножи, крепления и детали, которые больше негде купить и нечем заменить.","tags":["ремесло","металл"],"tip":"Спроси, чем чинить металл, когда сломается последний инструмент: кузница превращает металлолом в снаряжение."},{"id":"prof_08","title":"Швея-портниха","text":"Шьёт и латает одежду, умеет из старого тента сделать тёплый спальник и плотный фильтр для воды.","tags":["одежда","ремесло"],"tip":"Переведи разговор на тепло и одежду: ткань в бункере расходуется быстро, а ты продлеваешь ей жизнь в разы."},{"id":"prof_09","title":"Повар","text":"Готовит из чего угодно так, что это можно есть, и умеет растянуть недельный запас на целый месяц.","tags":["еда","быт"],"tip":"Скажи, что вкусная еда держит людей в форме: паёк однажды кончится, а умение готовить из остатков останется."},{"id":"prof_10","title":"Психолог","text":"Слышит ссору до того, как она началась, и умеет гасить панику в тесной комнате без единой таблетки.","tags":["психика","общение"],"tip":"Напомни, что люди в замкнутом пространстве срываются раньше, чем портится еда: ты спасаешь от того, чего нет в списке."},{"id":"prof_11","title":"Блогер","text":"Умеет говорить в камеру, продавать идеи и вести хронику. В бункере камера одна, и та давно сломана.","tags":["медиа","общение"],"tip":"Не оправдывайся: заяви, что держишь внимание людей и умеешь поднимать настроение словом, когда всем страшно."},{"id":"prof_12","title":"Таролог","text":"Раскладывает карты и уверенно говорит о будущем. Проверить точность предсказаний в бункере некому.","tags":["мистика","общение"],"tip":"Предложи себя как человека, который снимает тревогу: когда вокруг неизвестность, уверенный голос стоит дорого."},{"id":"prof_13","title":"Бариста","text":"Варит кофе из чего угодно и помнит наизусть вкусы тридцати постоянных гостей. Кофе в бункере нет.","tags":["еда","быт"],"tip":"Честно признай, что кофе не будет, но напомни: ты умеешь делать приятное из ничего, а это редкий навык."},{"id":"prof_14","title":"Актёр","text":"Может сыграть кого угодно и запомнить длинный текст с первого раза. В бункере зрителей маловато.","tags":["искусство","общение"],"tip":"Скажи, что умеешь разряжать обстановку и держать людей в тонусе: в тесном коллективе это защита от драк."},{"id":"prof_15","title":"Брокер","text":"Считает выгоду за секунды и договаривается с любым. Акции и деньги в бункере больше не работают.","tags":["деньги","общение"],"tip":"Предложи себя как переговорщика: в спорах за место нужен тот, кто умеет торговаться, и это твоя единственная валюта."},{"id":"prof_16","title":"Стендап-комик","text":"Пишет шутки про всё, включая конец света, и держит зал из трёх человек так же уверенно, как из трёхсот.","tags":["искусство","психика"],"tip":"Напомни, что смех сбивает панику: ты единственный, кто умеет превратить общий страх в шутку, пока другие молчат."},{"id":"prof_17","title":"Медсестра","text":"Ставит уколы, обрабатывает раны и знает, когда звать врача, а когда можно справиться своими руками.","tags":["медицина","быт"],"tip":"Спроси, кто будет ухаживать за больными каждый день: врач оперирует раз в месяц, а руки нужны постоянно."},{"id":"prof_18","title":"Сварщик","text":"Варит металл в любых условиях, режет броню и умеет заделать пробоину в главной двери за пару часов.","tags":["металл","защита"],"tip":"Заяви, что главная дверь бункера — твоя ответственность: пока она держит, все остальные споры становятся вторичны."},{"id":"prof_19","title":"Механик-дизелист","text":"Разбирает и собирает двигатель по памяти, слышит неисправность и делает детали из подручного металла.","tags":["техника","энергия"],"tip":"Уточни, что с генератором: пока он работает, бункер живой, и человек, который его чинит, важнее любого гуманитария."},{"id":"prof_20","title":"Фармацевт","text":"Разбирается в лекарствах, считает дозы и отличает нужную таблетку от яда в точно такой же упаковке.","tags":["медицина","наука"],"tip":"Спроси, кто разберёт аптечку без инструкции: перепутанная доза в бункере убивает быстрее самой болезни."},{"id":"prof_21","title":"Радиоинженер","text":"Собирает приёмник из хлама и ловит сигнал там, где остальные слышат только ровный шум помех.","tags":["связь","техника"],"tip":"Напомни, что связь с другими выжившими — это шанс на спасение: ты тот, кто может услышать, что творится снаружи."},{"id":"prof_22","title":"Геолог","text":"Читает породу и находит воду, руду и безопасные пустоты там, где снаружи сплошной камень.","tags":["наука","земля"],"tip":"Предложи искать воду и проверять грунт на прочность: без этого бункер останется без источника или рухнет."},{"id":"prof_23","title":"Пасечник","text":"Обращается с пчёлами, знает травы и делает из мёда еду, лекарство и клей одновременно.","tags":["еда","медицина"],"tip":"Спроси, чем заменить сахар и антибиотики: мёд закрывает оба пункта, и оспорить это трудно."},{"id":"prof_24","title":"Охотник-промысловик","text":"Ставит ловушки, читает следы и умеет добыть еду в лесу, где остальные видят только снег и ветки.","tags":["еда","выживание"],"tip":"Напомни про вылазки за периметр: когда запасы кончатся, кто-то должен уметь вернуться с добычей, а не с пустыми руками."},{"id":"prof_25","title":"Стоматолог","text":"Умеет вылечить зуб, вскрыть нарыв и снять боль, от которой человек не может ни есть, ни спать.","tags":["медицина","быт"],"tip":"Опиши, что будет с командой при зубной боли без врача: терпеть её месяцами не сможет даже самый крепкий."},{"id":"prof_26","title":"Строитель-каменщик","text":"Кладёт стены, укрепляет перекрытия и знает, где несущая балка, а где декоративная панель.","tags":["строительство","защита"],"tip":"Предложи проверить прочность убежища: без понимания конструкции любая авария в бункере станет последней."},{"id":"prof_27","title":"Учитель физики","text":"Объясняет сложное простыми словами и ставит опыты из подручных материалов вместо нормальных приборов.","tags":["наука","обучение"],"tip":"Скажи, что научишь остальных чинить и считать: в бункере ценен не только навык, но и тот, кто передаёт его другим."},{"id":"prof_28","title":"Часовщик","text":"Работает с мелкими механизмами, чинит замки и приборы, где деталь тоньше человеческого волоса.","tags":["ремесло","техника"],"tip":"Напомни, что точные механизмы ломаются чаще грубых: замки, фильтры и датчики в бункере больше починить некому."},{"id":"prof_29","title":"Программист","text":"Разбирается в незнакомой системе по инструкции и умеет часами не отвлекаться на посторонний шум.","tags":["техника","информация"],"tip":"Честно скажи, что кода в бункере нет, но заяви, что быстрее всех освоишь любой незнакомый пульт и прибор."},{"id":"prof_30","title":"Юрист","text":"Договаривается так, что условия соблюдают, и умеет писать правила, по которым людям понятно жить.","tags":["право","общение"],"tip":"Предложи себя на роль свода правил: в бункере без правил первыми гибнут слабые, и это ты можешь остановить."},{"id":"prof_31","title":"Курьер доставки","text":"Знает город наизусть, ходит по маршрутам в любую погоду и укладывается в срок без карт и навигатора.","tags":["логистика","выживание"],"tip":"Напомни про вылазки: маршрут, выносливость и умение вернуться вовремя — твой реальный козырь, а не велосипед."},{"id":"prof_32","title":"Сомелье","text":"Различает сотни вкусов и запахов и ведёт дегустацию так, что гости чувствуют себя важными людьми.","tags":["еда","быт"],"tip":"Скажи, что по вкусу и запаху определишь испорченную воду или еду: это не роскошь, а защита от отравления."},{"id":"prof_33","title":"Фокусник-иллюзионист","text":"Показывает фокусы, владеет отвлечением внимания и мелкой моторикой лучше любого карманника.","tags":["искусство","ловкость"],"tip":"Предложи роль разведчика внимания: ты умеешь отвлечь человека и незаметно достать нужное, а это уже навык."},{"id":"prof_34","title":"Тату-мастер","text":"Работает тонкой иглой, держит стерильность и не боится крови и чужой боли совсем рядом.","tags":["медицина","искусство"],"tip":"Заяви, что умеешь аккуратно работать с кожей и инструментом: при нехватке медиков это твой шанс на место."}]},"specials":{"category":"special","label":"Спец. возможность","icon":"⚡","cards":[{"id":"spec_01","title":"Публичное вскрытие","text":"Ты заставляешь любого игрока открыть одну закрытую характеристику: она станет видна всем до голосования.","tags":["контроль","информация"],"tip":"Держи до момента, когда против тебя собираются голоса: вскрытая чужая слабость мгновенно меняет расклад.","effect":"reveal_other","targeting":"one_player"},{"id":"spec_02","title":"Досье на игрока","text":"Ты требуешь, чтобы выбранный игрок открыл скрытую карту на всеобщее обозрение прямо сейчас.","tags":["информация","давление"],"tip":"Примени против лидера спора: когда все смотрят на его карту, защищаться ему становится труднее.","effect":"reveal_other","targeting":"one_player"},{"id":"spec_03","title":"Тайный обмен","text":"Ты обмениваешься одной закрытой картой с любым игроком: обмен происходит тайно и без права отказа.","tags":["обмен","контроль"],"tip":"Меняйся, когда у тебя откровенно слабая карта: выбери того, кто не понимает цену своей.","effect":"swap_card","targeting":"one_player"},{"id":"spec_04","title":"Подмена карты","text":"Ты подкладываешь любому игроку свою закрытую карту, а его карту забираешь себе вместо неё.","tags":["обмен","хитрость"],"tip":"Оставь это на конец: подмена в финале ломает защиту, которую соперник строил весь раунд.","effect":"swap_card","targeting":"one_player"},{"id":"spec_05","title":"Иммунитет на голосование","text":"Голоса против тебя в этом раунде не срабатывают: тебя нельзя изгнать до следующего круга.","tags":["защита","голосование"],"tip":"Объяви о защите заранее: часть игроков начнёт голосовать в другого, чтобы не тратить голос впустую.","effect":"immune_vote","targeting":"self"},{"id":"spec_06","title":"Железное алиби","text":"Ты предъявляешь алиби, и обвинения против тебя снимаются: в этом раунде тебя не изгоняют.","tags":["защита","репутация"],"tip":"Не молчи до конца: скажи о защите раньше, и соперники будут искать себе другую цель.","effect":"immune_vote","targeting":"self"},{"id":"spec_07","title":"Двойной голос","text":"Твой голос в этом голосовании считается за два: одно твоё решение весит как два мнения.","tags":["голосование","влияние"],"tip":"Голосуй последним: когда расклад ясен, двойной голос решает исход одним движением.","effect":"double_vote","targeting":"self"},{"id":"spec_08","title":"Поддержка союзников","text":"Двое твоих союзников отдают тебе свои голоса: твой голос в этом раунде считается за два.","tags":["голосование","союз"],"tip":"Договорись с союзниками заранее и не раскрывай сделку: сговор пугает остальных сильнее угроз.","effect":"double_vote","targeting":"self"},{"id":"spec_09","title":"Отмена голосования","text":"Ты отменяешь текущее голосование: голоса сбрасываются, и раунд заканчивается без изгнания.","tags":["голосование","контроль"],"tip":"Спасай этим себя или ключевого союзника: голосование повторится, но состав уже не изменится.","effect":"cancel_vote","targeting":"all"},{"id":"spec_10","title":"Сброс голосов","text":"Ты объявляешь переголосование: все поданные голоса сбрасываются и раунд начинается заново.","tags":["голосование","контроль"],"tip":"Пользуйся, когда видишь, что сговор решает исход: повторный круг ломает чужие договорённости.","effect":"cancel_vote","targeting":"all"},{"id":"spec_11","title":"Подсмотреть карту","text":"Ты тайно изучаешь характеристики любого игрока: его закрытые карты видишь только ты.","tags":["информация","хитрость"],"tip":"Не рассказывай всё сразу: знание о чужой слабости дороже стоит в момент голосования.","effect":"peek_other","targeting":"one_player"},{"id":"spec_12","title":"Чтение досье","text":"Ты читаешь чужое досье: скрытые характеристики выбранного игрока открываются лично тебе.","tags":["информация","контроль"],"tip":"Копи тайное знание: в споре одна точная фраза о чужой карте стоит десяти общих обвинений.","effect":"peek_other","targeting":"one_player"},{"id":"spec_13","title":"Курс лечения","text":"Ты проходишь лечение: твоя карта здоровья заменяется новой, вытянутой из колоды.","tags":["медицина","защита"],"tip":"Применяй к самой опасной своей карте: с диагнозом «смертельно» в бункер не берут никого.","effect":"heal_self","targeting":"self"},{"id":"spec_14","title":"Второе дыхание","text":"Ты восстанавливаешься после болезни: слабая карта здоровья уходит, вместо неё приходит крепкая.","tags":["медицина","здоровье"],"tip":"Меняй карту до голосования и покажи результат: здоровый человек нужен команде больше, чем умный.","effect":"heal_self","targeting":"self"},{"id":"spec_15","title":"Лишнее раскрытие","text":"Ты получаешь право открыть дополнительную карту сверх обычного лимита этого раунда.","tags":["раскрытие","влияние"],"tip":"Открывай сильную карту в тот момент, когда зал уже готов голосовать против тебя.","effect":"boost_self","targeting":"self"},{"id":"spec_16","title":"Внеплановая откровенность","text":"Ты раскрываешь ещё одну характеристику вне очереди: лимит этого раунда на тебя не действует.","tags":["раскрытие","защита"],"tip":"Прибереги для раунда, где тебе нечего показать: лишняя карта даёт новый аргумент в споре.","effect":"boost_self","targeting":"self"},{"id":"spec_17","title":"Продлить обсуждение","text":"Ты выторговываешь ещё тридцать секунд: таймер текущей фазы продлевается для всех игроков.","tags":["время","контроль"],"tip":"Бери паузу, когда спор идёт против тебя: лишние минуты дают шанс переломить настроение зала.","effect":"extra_time","targeting":"all"},{"id":"spec_18","title":"Время на подготовку","text":"Ты даёшь всем дополнительное время: фаза продлевается, и решения принимаются спокойнее.","tags":["время","переговоры"],"tip":"Проси время, когда тебя обвиняют в спешке: спокойный разбор снимает самые громкие обвинения.","effect":"extra_time","targeting":"all"},{"id":"spec_19","title":"Возврат в игру","text":"Ты возвращаешь изгнанного игрока в лагерь: он снова участвует в обсуждении и голосовании.","tags":["голосование","союз"],"tip":"Возвращай того, кто будет голосовать с тобой: союзник из временного лагеря обязан тебе местом.","effect":"return_player","targeting":"one_player"},{"id":"spec_20","title":"Второй шанс","text":"Ты даёшь одному изгнанному игроку второй шанс и возвращаешь его за стол переговоров.","tags":["союз","милосердие"],"tip":"Выбирай того, кого изгнали из-за случайности: он будет защищать тебя до конца партии.","effect":"return_player","targeting":"one_player"},{"id":"spec_21","title":"Новая карта","text":"Ты сдаёшь свою закрытую карту обратно в колоду и тянешь вместо неё другую характеристику.","tags":["карта","шанс"],"tip":"Меняй карту до раскрытия: если слабая характеристика уже открыта, эффект почти бесполезен.","effect":"reroll_card","targeting":"self"},{"id":"spec_22","title":"Пересдача","text":"Ты тянешь замену любой своей закрытой карты: колода выдаёт другую характеристику наугад.","tags":["карта","шанс"],"tip":"Рискуй, когда терять нечего: карта хуже текущей встречается редко, а выигрыш бывает решающим.","effect":"reroll_card","targeting":"self"},{"id":"spec_23","title":"Лишить слова","text":"Ты запрещаешь любому игроку говорить до конца раунда: его доводы больше не прозвучат.","tags":["контроль","давление"],"tip":"Выключай того, кто громче всех обвиняет: без его напора обвинения против тебя рассыпаются сами.","effect":"silence_player","targeting":"one_player"},{"id":"spec_24","title":"Тишина в зале","text":"Ты накладываешь молчание на выбранного игрока: он пропускает свою очередь высказаться.","tags":["контроль","голосование"],"tip":"Применяй перед голосованием: тот, кто не успел возразить, рискует остаться без поддержки зала.","effect":"silence_player","targeting":"one_player"}]},"traits":{"category":"trait","label":"Характер","icon":"🎭","cards":[{"id":"trait_01","title":"Спокойный под давлением","text":"В аварийной ситуации говорит ровно и делает то, что нужно. Паника его не заражает даже в худший день.","tags":["спокойствие","лидерство"],"tip":"Напомни, что в бункере паника убивает быстрее голода: ты тот, кто принимает решения, когда все кричат."},{"id":"trait_02","title":"Паникёр","text":"При первой же проблеме теряет голову и заражает тревогой остальных. Зато замечает опасность раньше всех.","tags":["тревожность","внимательность"],"tip":"Признай слабость и продай её с другой стороны: ты первый замечаешь проблему, и группе это даёт время."},{"id":"trait_03","title":"Прирождённый лидер","text":"Берёт ответственность без просьбы и умеет распределить работу так, что никто не спорит.","tags":["лидерство","организация"],"tip":"Предложи себя вести смены и распределять задачи: без этого в бункере начнётся война за каждую мелочь."},{"id":"trait_04","title":"Упрямый до скрипа зубов","text":"Если решил — не свернёт. Начатое доводит до конца, но чужие доводы слышит только через силу.","tags":["упрямство","воля"],"tip":"Переведи упрямство в пользу: заяви, что не бросишь работу на середине, даже когда остальные сдались."},{"id":"trait_05","title":"Молчун","text":"Говорит редко и по делу. Слушает больше, чем рассказывает, и не тратит чужие нервы на пустые споры.","tags":["тишина","терпение"],"tip":"Скажи, что молчание — это экономия конфликтов: в тесном бункере тот, кто не ссорится, дороже болтуна."},{"id":"trait_06","title":"Болтун","text":"Говорит без остановки и на любую тему. Раздражает, но в гробовой тишине бункера держит людей в сознании.","tags":["общение","шум"],"tip":"Напомни, что тишина в замкнутом пространстве сводит с ума: ты заполняешь её и держишь людей живыми."},{"id":"trait_07","title":"Педант","text":"Всё раскладывает по местам и ведёт учёт до последней банки. Порядок держит идеально, но медленно.","tags":["порядок","учёт"],"tip":"Предложи вести учёт запасов: без учёта бункер съест месячный паёк за неделю и никто не заметит."},{"id":"trait_08","title":"Неряха","text":"Разбрасывает вещи и забывает убирать. Работает быстро, но найти что-то в его углу невозможно.","tags":["беспорядок","быт"],"tip":"Скажи честно, что порядок не твой, но предложи себя на грязную работу, которую никто не хочет делать."},{"id":"trait_09","title":"Всех жалеет","text":"Не может пройти мимо чужой боли и делится последним. В бункере такие запасы быстро заканчиваются.","tags":["доброта","риск"],"tip":"Признай мягкость, но напомни: тот, кто жалеет, не бросит раненого и не сбежит в опасный момент."},{"id":"trait_10","title":"Хладнокровный прагматик","text":"Считает выгоду в любой ситуации и без колебаний отрезает лишнее. Решения принимает быстро и жёстко.","tags":["расчёт","холодность"],"tip":"Заяви, что в бункере выживают не добрые, а расчётливые: ты тот, кто не постесняется принять тяжёлое решение."},{"id":"trait_11","title":"Вспыльчивый","text":"Взрывается за секунду и орёт так, что стены дрожат. Через десять минут отходит и работает как ни в чём не бывало.","tags":["гнев","конфликт"],"tip":"Не обещай стать мягким: скажи, что злость выходит быстро и без затаённого зла, а это лучше тихой обиды."},{"id":"trait_12","title":"Каменное терпение","text":"Может годами терпеть неудобства, тяжёлую работу и чужие выходки, не повышая голоса.","tags":["терпение","выносливость"],"tip":"Напомни, что в бункере жить долго: человек без терпения сломается на третий месяц, а ты продержишься все годы."},{"id":"trait_13","title":"Трусливый","text":"Боится опасности и старается держаться подальше от риска. Зато осторожен там, где другие лезут на рожон.","tags":["страх","осторожность"],"tip":"Переверни слабость: трус не полезет в опасное место и не погубит группу глупой выходкой."},{"id":"trait_14","title":"Отчаянный смельчак","text":"Лезет в опасность первым и не считает риск. Вытаскивает других, но и себя загоняет в беду.","tags":["смелость","риск"],"tip":"Предложи себя на вылазки: когда нужно рискнуть, ты идёшь добровольцем, а не жребий решает, кто пойдёт."},{"id":"trait_15","title":"Любопытный","text":"Суёт нос в каждый механизм и разбирает то, что работало. Иногда ломает, но чаще находит неожиданное.","tags":["любопытство","поиск"],"tip":"Скажи, что находишь то, что другие не ищут: любопытство в бункере превращается в разведку ресурсов."},{"id":"trait_16","title":"Подозрительный","text":"Никому не верит на слово и проверяет каждое обещание. С ним трудно дружить, но обмануть его сложно.","tags":["недоверие","внимательность"],"tip":"Заяви, что в группе нужен тот, кто проверяет: без этого один врун погубит всех остальных."},{"id":"trait_17","title":"Доверчивый","text":"Верит людям сразу и помогает, не проверяя. Обмануть его легко, зато он честен до конца.","tags":["доверие","честность"],"tip":"Признай наивность и продай честность: ты не будешь плести интриги и делиться будешь по-настоящему."},{"id":"trait_18","title":"Трудоголик","text":"Работает больше всех и сам не замечает, как берёт чужие смены. Отдыхать не умеет и других не понимает.","tags":["работа","выносливость"],"tip":"Скажи, что закрываешь две смены вместо одной: в бункере это буквально двойная польза от одного места."},{"id":"trait_19","title":"Ленивый","text":"Делает только то, что нельзя не сделать. Зато придумывает, как выполнить работу быстрее и с меньшим трудом.","tags":["лень","изобретательность"],"tip":"Переведи лень в изобретательность: заяви, что ищешь короткий путь, и это экономит силы всей группы."},{"id":"trait_20","title":"Оптимист","text":"В любой катастрофе находит повод для надежды и умеет заразить ею остальных. Иногда недооценивает опасность.","tags":["надежда","настроение"],"tip":"Напомни, что надежда — расходник: без неё люди в бункере сдаются быстрее, чем кончается еда."},{"id":"trait_21","title":"Пессимист","text":"Заранее ждёт худшего и готовится к нему. Портит настроение, но редко остаётся без плана на случай беды.","tags":["тревожность","планирование"],"tip":"Скажи, что готовность к худшему спасает: пока оптимисты расслабляются, ты уже приготовил план и запас."},{"id":"trait_22","title":"Скромный и незаметный","text":"Не спорит, не выпячивается и делает свою работу тихо. Заметить его трудно, а без него всё встанет.","tags":["скромность","работа"],"tip":"Опиши, что делаешь без напоминаний: в бункере тихий работник нужнее, чем громкий спорщик, и это видно на третий день."},{"id":"trait_23","title":"Тщеславный","text":"Любит быть в центре и требует признания заслуг. Ради похвалы готов работать больше и лучше остальных.","tags":["гордость","мотивация"],"tip":"Используй тщеславие как двигатель: скажи, что тебе нужно признание, а группе — результат, и оба получат своё."},{"id":"trait_24","title":"Врёт убедительно","text":"Придумывает на ходу и говорит так, что верит даже он сам. Разоблачить его почти невозможно.","tags":["ложь","общение"],"tip":"Не отрицай: заяви, что в переговорах с чужими твоя ложь — оружие, которое защищает бункер от лишних ртов."},{"id":"trait_25","title":"Честный до неудобства","text":"Говорит правду, даже когда лучше промолчать. Обижает людей, но ему можно доверять полностью.","tags":["честность","прямота"],"tip":"Напомни, что в бункере нужен человек, которому верят без проверки: твоя прямота экономит чужие нервы."},{"id":"trait_26","title":"Сентиментальный","text":"Помнит мелочи о каждом и хранит чужие вещи как память. В тяжёлый момент поддержит словом.","tags":["теплота","память"],"tip":"Скажи, что держишь людей вместе памятью и вниманием: в замкнутом коллективе это спасает от озлобления."},{"id":"trait_27","title":"Мстительный","text":"Помнит каждую обиду и ждёт момента вернуть долг. Может годами не показывать вида и выжидать.","tags":["обида","конфликт"],"tip":"Честно признай, что обид не прощаешь: зато никто в бункере не рискнёт тебя подставить."},{"id":"trait_28","title":"Миротворец","text":"Мирит ссорящихся и находит решение, которое устроит обоих. Умеет говорить с любым человеком.","tags":["переговоры","сплочение"],"tip":"Предложи роль переговорщика внутри группы: без такого человека бункер расколется на два лагеря за месяц."}]}};
